INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('7463da7a-f2bf-58f9-a736-3e303ee8c87f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 9, 9, 'An α-particle (charge +2e) moves at 3.0 × 10⁶ m s⁻¹ at right angles to a field of 0.50 T. Calculate the magnetic force on it, in units of 10⁻¹³ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4.8', '10⁻¹³ N', false, NULL, false, NULL, 'F = BQv = 0.50 × 2 × 1.60 × 10⁻¹⁹ × 3.0 × 10⁶ = 4.80 × 10⁻¹³ N. Mark scheme (2 marks). C1: F = BQv with Q = 2e. A1: F = 4.8 × 10⁻¹³ N.', 2),
('d07d0cd3-d372-5fb3-b5d8-3dca6507936a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 10, 10, 'When Fleming''s left-hand rule is used for a moving positive charge, which way does the second finger point?', NULL, 1, 'multiple_choice'::answer_type, 'Along the velocity of the charge', NULL, false, NULL, false, NULL, 'A moving positive charge is a conventional current in its direction of motion. Mark scheme (1 mark). B1: C (Along the velocity of the charge).', 1),
('041fa607-15b1-5f81-a323-55a34a2012a6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 11, 11, 'For an electron beam, in which direction should the "current" finger of the left-hand rule point?', NULL, 1, 'multiple_choice'::answer_type, 'Opposite to the electron''s velocity', NULL, false, NULL, false, NULL, 'Conventional current is opposite to the flow of negative charge. Mark scheme (1 mark). B1: A (Opposite to the electron''s velocity).', 1),
('9524f422-4099-5e91-afba-643eeadf4c48', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 12, 12, 'A proton moves at 4.0 × 10⁵ m s⁻¹ at 60° to a magnetic field of 0.25 T. Calculate the magnetic force on it, in units of 10⁻¹⁴ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.386', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = BQv sin θ = 0.25 × 1.60 × 10⁻¹⁹ × 4.0 × 10⁵ × sin 60° = 1.39 × 10⁻¹⁴ N. Mark scheme (2 marks). C1: F = BQv sin θ. A1: F = 1.39 × 10⁻¹⁴ N.', 2),
('a53c77bc-a009-5b27-8b68-2466bd3469f6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 13, 13, 'In F = BQv sin θ, what does θ represent?', NULL, 1, 'multiple_choice'::answer_type, 'The angle between the velocity of the charge and the magnetic field', NULL, false, NULL, false, NULL, 'Only the velocity component at right angles to B contributes. Mark scheme (1 mark). B1: D (The angle between the velocity of the charge and the magnetic field).', 1),
('d776c4b1-5d02-5ad1-ae65-8a916f8b3eaa', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 14, 14, 'An electron moving at right angles to a 0.50 T field experiences a magnetic force of 6.4 × 10⁻¹⁴ N. Calculate its speed. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8e5', 'm s⁻¹', false, NULL, false, NULL, 'v = F/(BQ) = 6.4 × 10⁻¹⁴ ÷ (0.50 × 1.60 × 10⁻¹⁹) = 8.0 × 10⁵ m s⁻¹. Mark scheme (2 marks). C1: v = F/(BQ). A1: v = 8.0 × 10⁵ m s⁻¹.', 2),
('3f2dd8ff-c66a-5571-84a7-b7fb54adc6ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 15, 15, 'What magnetic force acts on a charged particle that is at rest in a magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'None', NULL, false, NULL, false, NULL, 'F = BQv, and with v = 0 the magnetic force is zero. Mark scheme (1 mark). B1: B (None).', 1),
('5f518ed8-07cb-5cbf-ab77-d1e90be657d9', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 16, 16, 'A proton moving at 1.0 × 10⁶ m s⁻¹ at right angles to a magnetic field experiences a force of 3.2 × 10⁻¹⁴ N. Calculate the flux density. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.2', 'T', false, NULL, false, NULL, 'B = F/(Qv) = 3.2 × 10⁻¹⁴ ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁶) = 0.20 T. Mark scheme (2 marks). C1: B = F/(Qv). A1: B = 0.20 T.', 2),
('fdc5216c-2541-5516-8455-4b0878d80919', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 17, 17, 'The speed of a charged particle moving at right angles to a magnetic field doubles. What happens to the magnetic force on it?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'F = BQv, so with B and Q fixed the force is proportional to the speed. Mark scheme (1 mark). B1: C (It doubles).', 1),
('31e34274-0732-5a8e-88ec-519965c94f1f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 18, 18, 'What magnetic force, in units of 10⁻¹⁴ N, acts on a doubly charged ion crossing a 1.0 T field at right angles with speed 2.0 × 10⁵ m s⁻¹? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '6.4', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = BQv = 1.0 × 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = 6.40 × 10⁻¹⁴ N. Mark scheme (2 marks). C1: Q = 2e. A1: F = 6.4 × 10⁻¹⁴ N.', 2),
('c36692c9-7708-5219-b16f-bae650ab1594', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 19, 19, 'A charged particle moves through a uniform magnetic field and no other force acts. What happens to its kinetic energy?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'The force is always perpendicular to the motion, so no work is done. Mark scheme (1 mark). B1: A (It stays the same).', 1),
('c470a062-405d-5510-8763-812f7eda4dcc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 20, 20, 'A charged particle feels a magnetic force of 2.0 × 10⁻¹⁴ N when moving at right angles to a field. What force does it feel, in units of 10⁻¹⁴ N, moving at the same speed at 30° to the field?', NULL, 1, 'numeric'::answer_type, '1', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = 2.0 × 10⁻¹⁴ × sin 30° = 1.0 × 10⁻¹⁴ N. Mark scheme (1 mark). A1: F = 1.0 × 10⁻¹⁴ N.', 1),
('b6f065b8-c222-5883-8dbd-19e662e95b6a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 21, 21, 'A proton moves due east through a magnetic field that points vertically upwards. In which direction is the force on it?', NULL, 1, 'multiple_choice'::answer_type, 'Due south', NULL, false, NULL, false, NULL, 'Left-hand rule: first finger up, second finger east (positive charge), thumb points south. Mark scheme (1 mark). B1: D (Due south).', 1),
('399fe610-bd91-59c4-9916-ce778332bc9f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 22, 22, 'A proton and an α-particle move at the same speed at right angles to the same magnetic field. Calculate (force on α-particle) ÷ (force on proton).', NULL, 1, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'F = BQv and the α-particle has charge 2e: ratio = 2 × 1.60 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 2.0. Mark scheme (2 marks). C1: F ∝ Q. A1: ratio = 2.0.', 2),
('5bbe837b-47a2-57db-914c-4238d3069542', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 23, 23, 'Which step links F = BIL to the force on a single moving charge, F = BQv?', NULL, 1, 'multiple_choice'::answer_type, 'A charge Q moving at speed v forms a current I = Q/t over a length L = vt, so BIL = BQv', NULL, false, NULL, false, NULL, 'IL = (Q/t)(vt) = Qv. Mark scheme (1 mark). B1: B (A charge Q moving at speed v forms a current I = Q/t over a length L = vt, so BIL = BQv).', 1),
('1a0b9082-7ec5-5148-970d-4c9daf4e0dc2', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 24, 24, 'An electron moves at 1.0 × 10⁷ m s⁻¹ at right angles to the Earth''s field of 5.0 × 10⁻⁵ T. Calculate the magnetic force on it, in units of 10⁻¹⁷ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8', '10⁻¹⁷ N', false, NULL, false, NULL, 'F = BQv = 5.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 1.0 × 10⁷ = 8.00 × 10⁻¹⁷ N. Mark scheme (2 marks). C1: F = BQv. A1: F = 8.0 × 10⁻¹⁷ N.', 2),
('ff6dd8d1-5c3b-50d7-9d16-63b73e895759', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 25, 25, 'A beam of neutrons passes through a strong magnetic field. What happens to the beam?', NULL, 1, 'multiple_choice'::answer_type, 'It is not deflected, because neutrons are uncharged', NULL, false, NULL, false, NULL, 'The magnetic force needs a charge: F = BQv with Q = 0. Mark scheme (1 mark). B1: C (It is not deflected, because neutrons are uncharged).', 1),
('da4e215b-0b70-55bf-9092-3adac3cc1d5e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 26, 26, 'In an old television tube, electrons moving at 3.0 × 10⁷ m s⁻¹ cross a deflecting field of 2.0 mT at right angles. Calculate the acceleration of an electron. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '1.054e16', 'm s⁻²', false, NULL, false, NULL, 'F = BQv = 2.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 3.0 × 10⁷ = 9.60 × 10⁻¹⁵ N. a = F/m = 9.600 × 10⁻¹⁵ ÷ 9.11 × 10⁻³¹ = 1.05 × 10¹⁶ m s⁻². Mark scheme (3 marks). C1: F = BQv. C1: a = F/m. A1: a = 1.05 × 10¹⁶ m s⁻².', 3),
('673c4b1a-8903-5051-854d-9688fb1b167d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 27, 27, 'Free electrons drift at 2.0 × 10⁻⁴ m s⁻¹ along a copper wire that lies at right angles to a 0.50 T field. Calculate the magnetic force on one electron, in units of 10⁻²³ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.6', '10⁻²³ N', false, NULL, false, NULL, 'F = BQv = 0.50 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁻⁴ = 1.60 × 10⁻²³ N: tiny, but there are about 10²² free electrons in each centimetre of wire. Mark scheme (3 marks). C1: F = Bev. C1: substitution. A1: F = 1.6 × 10⁻²³ N.', 3),
('67c86dc5-95c2-5b23-a170-f4be8d355e03', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 28, 28, 'A proton and an electron move in the same direction at the same speed through the same magnetic field. How do the magnetic forces on them compare?', NULL, 2, 'multiple_choice'::answer_type, 'Equal in size and opposite in direction', NULL, false, NULL, false, NULL, 'F = BQv: same |Q|, v and B; the sign of Q reverses the direction. Mark scheme (3 marks). C1: same |Q|. C1: opposite sign gives opposite force. A1: A (Equal in size and opposite in direction).', 3),
('2d727d43-86e4-574c-9961-5cda8a44e5a5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 29, 29, 'A charged dust grain of mass 1.0 × 10⁻¹² kg carries 1.6 × 10⁻¹⁵ C and moves at 50 m s⁻¹ at right angles to a field of 0.40 T. Calculate its acceleration due to the magnetic force.', NULL, 2, 'numeric'::answer_type, '0.032', 'm s⁻²', false, NULL, false, NULL, 'F = BQv = 0.40 × 1.6 × 10⁻¹⁵ × 50 = 3.2 × 10⁻¹⁴ N. a = F/m = 3.2 × 10⁻¹⁴ ÷ 1.0 × 10⁻¹² = 0.032 m s⁻². Mark scheme (4 marks). C1: F = BQv. C1: a = F/m. B1: magnetic effect tiny for a slow, heavy grain. A1: a = 0.032 m s⁻².', 4),
('6b389ac8-3a52-5f1e-a025-5be7d135ab27', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 30, 30, 'With speed 5.0 × 10⁶ m s⁻¹, an electron crosses a 0.10 T field at 40° to the field lines. Find the magnetic force on it, in units of 10⁻¹⁴ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5.142', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = BQv sin θ = 0.10 × 1.60 × 10⁻¹⁹ × 5.0 × 10⁶ × sin 40° = 5.14 × 10⁻¹⁴ N. Mark scheme (3 marks). C1: F = BQv sin θ. C1: substitution. A1: F = 5.14 × 10⁻¹⁴ N.', 3),
('47964ae1-f4e8-53eb-9fb8-f0b1b58a5c73', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 31, 31, 'A charged particle enters a uniform magnetic field with its velocity at an acute angle to the field lines. What is the shape of its path?', NULL, 2, 'multiple_choice'::answer_type, 'A helix (spiral) along the field lines', NULL, false, NULL, false, NULL, 'The perpendicular velocity component gives circular motion; the parallel component carries it along the field. Mark scheme (3 marks). C1: components of velocity. C1: circle plus drift gives helix. A1: D (A helix (spiral) along the field lines).', 3),
('2794185d-cbd4-51e2-9eff-8600dc8cd4e8', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 32, 32, 'At what speed must a proton move at right angles to a 0.10 T field to feel a magnetic force of 1.0 × 10⁻¹³ N? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '6.25e6', 'm s⁻¹', false, NULL, false, NULL, 'v = F/(BQ) = 1.0 × 10⁻¹³ ÷ (0.10 × 1.60 × 10⁻¹⁹) = 6.25 × 10⁶ m s⁻¹. Mark scheme (3 marks). C1: rearranged. C1: substitution. A1: v = 6.25 × 10⁶ m s⁻¹.', 3),
('a9931ff0-860b-581c-b376-1af051974034', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 33, 33, 'An electron is accelerated from rest through 500 V and then moves at right angles to a field of 0.010 T. Calculate the magnetic force on it, in units of 10⁻¹⁴ N. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '2.12', '10⁻¹⁴ N', false, NULL, false, NULL, 'v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 500 ÷ 9.11 × 10⁻³¹) = 1.33 × 10⁷ m s⁻¹. F = BQv = 0.010 × 1.60 × 10⁻¹⁹ × 1.325 × 10⁷ = 2.12 × 10⁻¹⁴ N. Mark scheme (4 marks). C1: ½mv² = eV. C1: speed. C1: F = BQv. A1: F = 2.12 × 10⁻¹⁴ N.', 4),
('7698bd80-6cf0-53b7-a8cc-c3df7125bc26', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 34, 34, 'Why are auroras seen mainly near the Earth''s magnetic poles?', NULL, 2, 'multiple_choice'::answer_type, 'Charged particles from the Sun spiral along the field lines, which converge and enter the atmosphere near the poles', NULL, false, NULL, false, NULL, 'Motion along the field is unaffected, so particles follow the field lines down near the poles. Mark scheme (3 marks). C1: spiral along field lines. C1: lines enter atmosphere near poles. A1: B (Charged particles from the Sun spiral along the field lines, which converge and enter the atmosphere near the poles).', 3),
('6d4e6de5-fd84-5393-ac5f-add7710944b6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 35, 35, 'An ion moving at 2.0 × 10⁵ m s⁻¹ at right angles to a 0.50 T field feels a force of 3.2 × 10⁻¹⁴ N. Calculate its charge, as a multiple of e. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'Q = F/(Bv) = 3.2 × 10⁻¹⁴ ÷ (0.50 × 2.0 × 10⁵) = 3.2 × 10⁻¹⁹ C, and 3.2 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 2.0. Mark scheme (3 marks). C1: Q = F/(Bv). C1: ÷ e. A1: Q/e = 2.0.', 3),
('84434522-a263-52ec-ab93-25679563cf49', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 36, 36, 'The charge of a particle is doubled and its speed is halved, in the same field. What happens to the magnetic force on it?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'F = BQv: doubling Q and halving v leaves the product Qv, and so F, unchanged. Mark scheme (4 marks). C1: F ∝ Qv. C1: product unchanged. C1: same field. A1: C (It stays the same).', 4),
('1e35e5f6-b0da-517e-b87a-b5b77eaedde5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 37, 37, 'A charged particle feels half the maximum possible magnetic force for its speed. Calculate the angle between its velocity and the field.', NULL, 2, 'numeric'::answer_type, '30', '°', false, NULL, false, NULL, 'sin θ = 0.50, so θ = sin⁻¹ 0.50 = 30°. Mark scheme (3 marks). C1: F = F_max sin θ. C1: inverse sine. A1: θ = 30°.', 3),
('62020a8f-e050-5a72-a25d-aeb7beb2fbcb', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 38, 38, 'A singly charged ion moves at 4.0 × 10⁴ m s⁻¹ at right angles to a 0.60 T field in a mass spectrometer. Calculate the magnetic force on it, in units of 10⁻¹⁵ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.84', '10⁻¹⁵ N', false, NULL, false, NULL, 'F = BQv = 0.60 × 1.60 × 10⁻¹⁹ × 4.0 × 10⁴ = 3.84 × 10⁻¹⁵ N. Mark scheme (3 marks). C1: F = BQv. C1: substitution. A1: F = 3.84 × 10⁻¹⁵ N.', 3),
('75ba8a70-dccc-5693-95c0-03fa8d5f21c1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 39, 39, 'Several beams pass at right angles through a magnetic field. Which beam is NOT deflected?', NULL, 2, 'multiple_choice'::answer_type, 'A beam of neutrons', NULL, false, NULL, false, NULL, 'Neutrons carry no charge. Mark scheme (3 marks). C1: force needs charge. C1: neutrons neutral. A1: A (A beam of neutrons).', 3),
('0818c296-35a3-5777-80a9-d40ce722b3be', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 40, 40, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at right angles to a field of 3.0 mT. Calculate its acceleration. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '1.054e15', 'm s⁻²', false, NULL, false, NULL, 'F = BQv = 3.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 2.0 × 10⁶ = 9.60 × 10⁻¹⁶ N. a = 9.600 × 10⁻¹⁶ ÷ 9.11 × 10⁻³¹ = 1.05 × 10¹⁵ m s⁻². Mark scheme (4 marks). C1: field in T. C1: F = BQv. C1: a = F/m. A1: a = 1.05 × 10¹⁵ m s⁻².', 4),
('59d18be4-82d4-55b6-8a2b-11f625f248f4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 41, 41, 'An electron moves due north in a magnetic field that points vertically downwards. In which direction is the force on it?', NULL, 2, 'multiple_choice'::answer_type, 'Due east', NULL, false, NULL, false, NULL, 'Conventional current is due south; left-hand rule with first finger down and second finger south gives a thumb pointing east. Mark scheme (3 marks). C1: current opposite to electron velocity. C1: left-hand rule. A1: D (Due east).', 3),
('59e18f08-fb11-52d7-8ff6-8ba15b44cffc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 42, 42, 'A copper wire of cross-sectional area 1.0 × 10⁻⁶ m² carries 5.0 A. Copper has 8.5 × 10²⁸ free electrons per m³. The wire lies at right angles to a field of 0.20 T. (a) Calculate the drift speed of the electrons. (b) Calculate the magnetic force on one electron, in units of 10⁻²³ N. (c) Show that the total force on all the free electrons in 0.10 m of wire equals BIL. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.176', '10⁻²³ N', false, NULL, false, NULL, '(a) v = I/(nAe) = 5.0 ÷ (8.5 × 10²⁸ × 1.0 × 10⁻⁶ × 1.60 × 10⁻¹⁹) = 3.68 × 10⁻⁴ m s⁻¹. (b) F = Bev = 0.20 × 1.60 × 10⁻¹⁹ × 3.676 × 10⁻⁴ = 1.18 × 10⁻²³ N. (c) Number of electrons = nAL = 8.5 × 10²⁸ × 1.0 × 10⁻⁶ × 0.10 = 8.5 × 10²¹; total = 8.5 × 10²¹ × 1.176 × 10⁻²³ = 0.10 N, and BIL = 0.20 × 5.0 × 0.10 = 0.10 N. Mark scheme (6 marks). C1: v = I/(nAe). C1: F = Bev. C1: number of electrons nAL. M1: total force. B1: equals BIL. A1: F = 1.18 × 10⁻²³ N.', 6),
('3489a9b0-f103-5e2c-a8d5-608b1da8077c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 43, 43, 'A proton in the solar wind moves at 4.0 × 10⁵ m s⁻¹ at right angles to the Earth''s field, which is 3.0 × 10⁻⁵ T at that height. (a) Calculate the magnetic force on the proton. (b) Calculate its acceleration. (c) Explain why its speed does not change. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '1.15e9', 'm s⁻²', false, NULL, false, NULL, '(a) F = BQv = 3.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 4.0 × 10⁵ = 1.92 × 10⁻¹⁸ N. (b) a = 1.920 × 10⁻¹⁸ ÷ 1.67 × 10⁻²⁷ = 1.15 × 10⁹ m s⁻². (c) The force is always at right angles to the velocity, so it changes only the direction of motion. Mark scheme (5 marks). C1: F = BQv. C1: a = F/m. C1: substitution. B1: perpendicular force, no work. A1: a = 1.15 × 10⁹ m s⁻².', 5),
('b2ddcedd-bdea-5dfc-a5f0-8e4ee1a826ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 44, 44, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at 30° to a uniform field of 5.0 mT. (a) Calculate the components of its velocity parallel and perpendicular to the field. (b) Calculate the radius of its helical path, using r = mv⊥/eB. (c) Calculate the time for one revolution, T = 2πm/eB. (d) Calculate the pitch of the helix (the distance moved along the field in one revolution), in cm. Give only the answer to (d). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '1.239 cm', 'cm', false, NULL, false, NULL, '(a) v∥ = 2.0 × 10⁶ × cos 30° = 1.73 × 10⁶ m s⁻¹; v⊥ = 2.0 × 10⁶ × sin 30° = 1.0 × 10⁶ m s⁻¹. (b) r = 9.11 × 10⁻³¹ × 1.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻³) = 0.00114 m. (c) T = 2π × 9.11 × 10⁻³¹ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻³) = 7.15 × 10⁻⁹ s. (d) Pitch = v∥T = 1.732 × 10⁶ × 7.155 × 10⁻⁹ = 0.0124 m. In cm: 0.01239 × 100 = 1.24. Mark scheme (6 marks). C1: velocity components. C1: radius. C1: period. M1: pitch = v∥T. C1: conversion. A1: pitch = 1.24 cm.', 6),
('b6cd3e0a-fb68-563b-938a-82c7be34f95e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 45, 45, 'Sea water flows at 2.0 m s⁻¹ along a horizontal channel 0.20 m wide, at right angles to a vertical field of 0.50 T. (a) Explain why positive and negative ions are pushed to opposite sides of the channel. (b) Calculate the magnetic force on an ion of charge e. (c) The separation continues until the electric field across the channel is vB. Calculate the p.d. across the channel. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '0.2', 'V', false, NULL, false, NULL, '(a) F = BQv: ions of opposite sign moving the same way feel opposite forces. (b) F = 0.50 × 1.60 × 10⁻¹⁹ × 2.0 = 1.60 × 10⁻¹⁹ N. (c) E = vB = 2.0 × 0.50 = 1.0 V m⁻¹, so V = Ed = 1.0 × 0.20 = 0.20 V. Mark scheme (5 marks). B1: opposite charges, opposite forces. C1: F = BQv. M1: E = vB at equilibrium. C1: V = Ed. A1: V = 0.20 V.', 5),
('7a33672a-bd6b-525b-9c7b-ed79ef1c9f19', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 46, 46, 'An ion of charge 3e moves at right angles to a field of 0.25 T and experiences a force of 1.2 × 10⁻¹³ N. (a) Calculate its speed. (b) Its mass is 6.6 × 10⁻²⁶ kg. Calculate its kinetic energy. (c) Explain why this kinetic energy stays constant in the field. Give only the answer to (a). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1e6', 'm s⁻¹', false, NULL, false, NULL, '(a) v = F/(BQ) = 1.2 × 10⁻¹³ ÷ (0.25 × 3 × 1.60 × 10⁻¹⁹) = 1.00 × 10⁶ m s⁻¹. (b) E_k = 0.5 × 6.6 × 10⁻²⁶ × (1.000 × 10⁶)² = 3.30 × 10⁻¹⁴ J. (c) The magnetic force does no work because it is perpendicular to the velocity. Mark scheme (5 marks). C1: Q = 3e. C1: v = F/(BQ). C1: ½mv². B1: no work done. A1: v = 1.00 × 10⁶ m s⁻¹.', 5),
('3a66684a-698f-5dab-9615-3fa306284695', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 47, 47, 'The magnetic force on electrons of fixed speed in a 0.10 T field is measured for different angles θ between their velocity and the field: θ/° = 0, 30, 60, 90 and F/10⁻¹⁴ N = 0, 2.4, 4.2, 4.8. (a) Show that F ∝ sin θ. (b) Use the reading at 90° to find the speed of the electrons. (c) Predict the force at 45°, in units of 10⁻¹⁴ N. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '3e6', 'm s⁻¹', false, NULL, false, NULL, '(a) F/sin θ = 2.4 ÷ 0.50 = 4.8, 4.2 ÷ 0.866 = 4.85 and 4.8 ÷ 1 = 4.8 (×10⁻¹⁴ N): constant. (b) v = F/(Be) = 4.8 × 10⁻¹⁴ ÷ (0.10 × 1.60 × 10⁻¹⁹) = 3.0 × 10⁶ m s⁻¹. (c) F = 4.8 × 10⁻¹⁴ × sin 45° = 3.39 × 10⁻¹⁴ N. Mark scheme (6 marks). C1: F/sin θ values. B1: constant. C1: v = F/(Be). C1: substitution. C1: prediction. A1: v = 3.0 × 10⁶ m s⁻¹.', 6),
('89313f6e-62de-5d3f-ab9e-bd173761af00', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 48, 48, 'In a mass spectrometer, a singly charged ion of mass 4.0 × 10⁻²⁶ kg moves at 1.0 × 10⁵ m s⁻¹ at right angles to a field of 0.10 T. (a) Calculate the magnetic force. (b) Calculate its weight. (c) Calculate (magnetic force) ÷ (weight) and comment. Give only the ratio. Take e = 1.60 × 10⁻¹⁹ C and g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '4.077e9', NULL, false, NULL, false, NULL, '(a) F = 0.10 × 1.60 × 10⁻¹⁹ × 1.0 × 10⁵ = 1.6 × 10⁻¹⁵ N. (b) W = 4.0 × 10⁻²⁶ × 9.81 = 3.92 × 10⁻²⁵ N. (c) Ratio = 1.6 × 10⁻¹⁵ ÷ 3.924 × 10⁻²⁵ = 4.08 × 10⁹: gravity is completely negligible. Mark scheme (5 marks). C1: F = BQv. C1: W = mg. C1: ratio. B1: gravity negligible. A1: ratio = 4.08 × 10⁹.', 5),
('55decc7d-7f29-522c-9b5a-b4dfd605d465', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 49, 49, 'Electrons are accelerated from rest through 1.2 kV and then enter a field of 0.80 mT at right angles. (a) Calculate their speed. (b) Calculate the magnetic force on each electron, in units of 10⁻¹⁵ N. (c) Calculate the acceleration. (d) Explain why they move in a circle. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '2.628', '10⁻¹⁵ N', false, NULL, false, NULL, '(a) v = √(2 × 1.60 × 10⁻¹⁹ × 1200 ÷ 9.11 × 10⁻³¹) = 2.05 × 10⁷ m s⁻¹. (b) F = 0.80 × 10⁻³ × 1.60 × 10⁻¹⁹ × 2.053 × 10⁷ = 2.63 × 10⁻¹⁵ N. (c) a = F/m = 2.628 × 10⁻¹⁵ ÷ 9.11 × 10⁻³¹ = 2.88 × 10¹⁵ m s⁻². (d) The force is constant in size and always perpendicular to the velocity, so it is a centripetal force. Mark scheme (6 marks). C1: ½mv² = eV. C1: F = BQv. C1: a = F/m. B1: perpendicular constant force. B1: centripetal. A1: F = 2.63 × 10⁻¹⁵ N.', 6),
('c67ef2ac-fcd5-52da-868a-e45b3070758e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 50, 50, 'A proton and an α-particle (charge 2e, mass 4mₚ) are accelerated from rest through the same p.d. and enter the same magnetic field at right angles. (a) Show that the α-particle''s speed is 1/√2 of the proton''s. (b) Calculate (magnetic force on α-particle) ÷ (magnetic force on proton). Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.414', NULL, false, NULL, false, NULL, '(a) ½mv² = QV gives v = √(2QV/m); for the α-particle Q/m is half that of the proton, so v is 1/√2 as large. (b) F = BQv: ratio = 2 × (1/√2) = √2 = 1.41. Mark scheme (5 marks). M1: v = √(2QV/m). B1: v ratio 1/√2. C1: F ∝ Qv. C1: ratio. A1: ratio = 1.41.', 5)
