('36ccc4f5-f71d-5f50-b1b0-8a56fe785bbe', 'a53c77bc-a009-5b27-8b68-2466bd3469f6', 'The angle between the force and the field', 'A', false, 0),
('a90ba12d-6dd2-5b3a-a069-997dad2fef96', 'a53c77bc-a009-5b27-8b68-2466bd3469f6', 'The angle between the force and the velocity', 'B', false, 1),
('475c5868-029f-5cf0-b2d5-051451165f24', 'a53c77bc-a009-5b27-8b68-2466bd3469f6', 'The angle of the field to the horizontal', 'C', false, 2),
('8f518310-51e6-53f7-a636-99e474186339', 'a53c77bc-a009-5b27-8b68-2466bd3469f6', 'The angle between the velocity of the charge and the magnetic field', 'D', true, 3),
('6b35368d-3c39-57c3-98d8-3fd35149bd69', '3f2dd8ff-c66a-5571-84a7-b7fb54adc6ec', 'BQ', 'A', false, 0),
('7aa4658e-0e5f-5d0d-a2a5-e6f47d58edcd', '3f2dd8ff-c66a-5571-84a7-b7fb54adc6ec', 'None', 'B', true, 1),
('d17df516-9b69-5620-b05e-d1d2f0d6c562', '3f2dd8ff-c66a-5571-84a7-b7fb54adc6ec', 'BQ multiplied by the speed of light', 'C', false, 2),
('58713875-a7ef-52d8-908e-dbabadcecea2', '3f2dd8ff-c66a-5571-84a7-b7fb54adc6ec', 'A force along the field lines', 'D', false, 3),
('a2fbeeba-deff-53fb-b2c8-427deab58d6a', 'fdc5216c-2541-5516-8455-4b0878d80919', 'It halves', 'A', false, 0),
('2a97abb2-5599-5e3f-9f18-6d25562cbcfb', 'fdc5216c-2541-5516-8455-4b0878d80919', 'It quadruples', 'B', false, 1),
('0a1d3c76-61d9-51e2-a530-5a7b7deb0e02', 'fdc5216c-2541-5516-8455-4b0878d80919', 'It doubles', 'C', true, 2),
('bcc062d9-eed7-5604-992a-a70efa10ad83', 'fdc5216c-2541-5516-8455-4b0878d80919', 'It stays the same', 'D', false, 3),
('ea57d822-38e6-5817-8fa1-84cc3986cd93', 'c36692c9-7708-5219-b16f-bae650ab1594', 'It stays the same', 'A', true, 0),
('2f8fe232-d709-55d8-914e-b3252ecd2e20', 'c36692c9-7708-5219-b16f-bae650ab1594', 'It increases steadily', 'B', false, 1),
('fbe55d0c-7da1-5e49-af40-b37c01761af3', 'c36692c9-7708-5219-b16f-bae650ab1594', 'It decreases steadily', 'C', false, 2),
('5a88b925-10b4-593d-9eff-2d149685a02e', 'c36692c9-7708-5219-b16f-bae650ab1594', 'It becomes zero', 'D', false, 3),
('a7e23b51-dcf6-5c4f-a0c9-15b0860d7b29', 'b6f065b8-c222-5883-8dbd-19e662e95b6a', 'Due north', 'A', false, 0),
('ce8626a6-2ada-55ba-af93-7cd865bad6c8', 'b6f065b8-c222-5883-8dbd-19e662e95b6a', 'Vertically downwards', 'B', false, 1),
('392e1658-9e69-5dcd-b2e6-79f5e97f4be3', 'b6f065b8-c222-5883-8dbd-19e662e95b6a', 'Due west', 'C', false, 2),
('b35f990a-a572-5d73-8f6d-008e2d836865', 'b6f065b8-c222-5883-8dbd-19e662e95b6a', 'Due south', 'D', true, 3),
('50aff2db-fc3e-5209-a3cd-e02e9e0362c2', '5bbe837b-47a2-57db-914c-4238d3069542', 'The current is equal to the speed of the charge', 'A', false, 0),
('d414f1a0-dc2e-5210-b5c8-04d4b1a3a65c', '5bbe837b-47a2-57db-914c-4238d3069542', 'A charge Q moving at speed v forms a current I = Q/t over a length L = vt, so BIL = BQv', 'B', true, 1),
('78e7521d-8617-57d0-b314-e8a839c0072c', '5bbe837b-47a2-57db-914c-4238d3069542', 'The length is equal to the charge', 'C', false, 2),
('9746b447-d620-5b84-839f-033a2a960d34', '5bbe837b-47a2-57db-914c-4238d3069542', 'B is equal to Q/v', 'D', false, 3),
('549f779c-2c4e-5468-b536-eaf99b226af2', 'ff6dd8d1-5c3b-50d7-9d16-63b73e895759', 'It curves into a circle', 'A', false, 0),
('941d3026-da3f-5fba-aa23-8ee768f9a35a', 'ff6dd8d1-5c3b-50d7-9d16-63b73e895759', 'It is deflected towards the north pole', 'B', false, 1),
('b7815856-2c78-544f-bf5d-e284aefc30d1', 'ff6dd8d1-5c3b-50d7-9d16-63b73e895759', 'It is not deflected, because neutrons are uncharged', 'C', true, 2),
('36761626-ff0d-57ea-a389-fdffe1d4a10e', 'ff6dd8d1-5c3b-50d7-9d16-63b73e895759', 'It slows down', 'D', false, 3),
('07328e31-d635-504b-898f-2f9fd7199bdc', '67c86dc5-95c2-5b23-a170-f4be8d355e03', 'Equal in size and opposite in direction', 'A', true, 0),
('7c3c76db-f31f-57d4-b394-f2fd14016b07', '67c86dc5-95c2-5b23-a170-f4be8d355e03', 'Equal in size and in the same direction', 'B', false, 1),
('b055a32b-dabd-5d57-abb8-ed8abcb54744', '67c86dc5-95c2-5b23-a170-f4be8d355e03', 'The force on the proton is 1840 times larger', 'C', false, 2),
('58a9be50-3ceb-51b0-9e29-49fa5badd7e0', '67c86dc5-95c2-5b23-a170-f4be8d355e03', 'The force on the electron is 1840 times larger', 'D', false, 3),
('19255d6d-4492-53c0-901f-6b7dd6cc4988', '47964ae1-f4e8-53eb-9fb8-f0b1b58a5c73', 'A circle in a plane containing the field', 'A', false, 0),
('632374ca-c3c7-5c86-8c06-279373b3567c', '47964ae1-f4e8-53eb-9fb8-f0b1b58a5c73', 'A straight line along the field', 'B', false, 1),
('f6b0fab5-1e36-5322-bcc1-dbb9ea59a9f7', '47964ae1-f4e8-53eb-9fb8-f0b1b58a5c73', 'A parabola', 'C', false, 2),
('0c27e41d-9ee7-5cf8-8773-150604b36e04', '47964ae1-f4e8-53eb-9fb8-f0b1b58a5c73', 'A helix (spiral) along the field lines', 'D', true, 3),
('a1115fc5-8c00-5b2c-8698-8197d8452bc1', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'The Earth''s field repels particles from the equator', 'A', false, 0),
('3105c753-9a3f-51fd-9369-acf71cbaf17c', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'Charged particles from the Sun spiral along the field lines, which converge and enter the atmosphere near the poles', 'B', true, 1),
('ede35452-bd36-52c5-8b55-ee724fc5538e', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'The poles are colder, so the air glows', 'C', false, 2),
('41c552e0-5bef-545e-998e-df6c7dcc1eaa', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'Neutral particles are attracted to the poles', 'D', false, 3),
('914025cc-d97f-5594-a42c-deaab1f501c6', '84434522-a263-52ec-ab93-25679563cf49', 'It doubles', 'A', false, 0),
('bb4ba48c-9f80-5079-a990-bb3b89887251', '84434522-a263-52ec-ab93-25679563cf49', 'It halves', 'B', false, 1),
('f8063668-600c-5949-85d1-8f9581c8107f', '84434522-a263-52ec-ab93-25679563cf49', 'It stays the same', 'C', true, 2),
('4f751446-2504-5fe2-8cbd-3686cf074bd6', '84434522-a263-52ec-ab93-25679563cf49', 'It quadruples', 'D', false, 3),
('0cc42ac1-665d-50c9-89bc-59c96190befb', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of neutrons', 'A', true, 0),
('a02ca1bd-a599-5b61-99cb-d4b71166f27a', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of protons', 'B', false, 1),
('16a7939b-301b-5ee5-94f0-26503864ca7f', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of electrons', 'C', false, 2),
('e1210971-65fa-5bd7-b664-a481a1c755fd', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of α-particles', 'D', false, 3),
('53b95b51-409d-58fe-b947-cb198081c7d7', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Due west', 'A', false, 0),
('ec776a9f-679c-531d-813e-c81bb8b1641a', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Due south', 'B', false, 1),
('9316bdc4-5ae7-55de-983f-b9004bdef674', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Vertically upwards', 'C', false, 2),
('40c2f773-ff86-5ab1-b0d3-6063607e5764', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Due east', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('58efb69e-fe52-59ba-8087-c064249f02f2', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 7, 7, 'A proton moves at 1.0 × 10⁶ m s⁻¹ at right angles to a field of 0.50 T. Calculate the radius of its circular path, in cm, using r = mv/BQ. Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '2.088 cm', 'cm', false, NULL, false, NULL, 'r = mv/BQ = 1.67 × 10⁻²⁷ × 1.0 × 10⁶ ÷ (0.50 × 1.60 × 10⁻¹⁹) = 0.0209 m. In cm: 0.02088 × 100 = 2.09. Mark scheme (2 marks). C1: r = mv/BQ. A1: r = 2.09 cm.', 2),
('92193abf-512c-5ad8-b6fd-cca4734fe48e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 8, 8, 'How is the equation r = mv/BQ for a charged particle in a magnetic field obtained?', NULL, 1, 'multiple_choice'::answer_type, 'By equating the magnetic force BQv to the centripetal force mv²/r', NULL, false, NULL, false, NULL, 'BQv = mv²/r gives r = mv/BQ. Mark scheme (1 mark). B1: C (By equating the magnetic force BQv to the centripetal force mv²/r).', 1),
('b6cbeceb-a11e-53d4-ba3b-624a96d0a5bc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 9, 9, 'An α-particle (mass 6.64 × 10⁻²⁷ kg, charge 2e) moves at 2.0 × 10⁶ m s⁻¹ at right angles to a 1.0 T field. Calculate the radius of its path. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.0415', 'm', false, NULL, false, NULL, 'r = mv/BQ = 6.64 × 10⁻²⁷ × 2.0 × 10⁶ ÷ (1.0 × 2 × 1.60 × 10⁻¹⁹) = 0.0415 m. Mark scheme (2 marks). C1: Q = 2e in r = mv/BQ. A1: r = 0.0415 m.', 2),
('aab60ce3-8526-5108-96d0-ea8a5d86e6ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 10, 10, 'The flux density acting on a circling charged particle is doubled. What happens to the radius of its path?', NULL, 1, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'r = mv/BQ, so r ∝ 1/B. Mark scheme (1 mark). B1: A (It halves).', 1),
('deb15167-54cb-562d-b689-2895774ec82d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 11, 11, 'A proton moves in a circle of radius 0.10 m in a field of 0.20 T. Calculate its momentum, in units of 10⁻²¹ kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.2', '10⁻²¹ kg m s⁻¹', false, NULL, false, NULL, 'p = mv = BQr = 0.20 × 1.60 × 10⁻¹⁹ × 0.10 = 3.20 × 10⁻²¹ kg m s⁻¹. Mark scheme (2 marks). C1: p = BQr. A1: p = 3.2 × 10⁻²¹ kg m s⁻¹.', 2),
('2e43f98b-90d1-5209-a7f1-54f0d22509a6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 12, 12, 'How does the time for one orbit of a charged particle in a uniform field depend on its speed?', NULL, 1, 'multiple_choice'::answer_type, 'It does not depend on the speed', NULL, false, NULL, false, NULL, 'T = 2πm/BQ: faster particles move in larger circles, taking the same time. Mark scheme (1 mark). B1: D (It does not depend on the speed).', 1),
('33e5f99a-5ecd-558f-996b-4c9290bb1cc4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 13, 13, 'Calculate the period of a proton circling in a 1.0 T field, in ns, using T = 2πm/BQ. Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '65.58 ns', 'ns', false, NULL, false, NULL, 'T = 2π × 1.67 × 10⁻²⁷ ÷ (1.0 × 1.60 × 10⁻¹⁹) = 6.56 × 10⁻⁸ s. In ns: 6.558 × 10⁻⁸ × 10⁹ = 65.6. Mark scheme (2 marks). C1: T = 2πm/BQ. A1: T = 65.6 ns.', 2),
('32f8c1c7-65d9-5615-9b36-e04483e9ccaa', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 14, 14, 'Two particles with the same charge and speed enter the same magnetic field. Particle X has the larger mass. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'X moves in the larger circle', NULL, false, NULL, false, NULL, 'r = mv/BQ, so with v, B and Q the same the radius is proportional to the mass. Mark scheme (1 mark). B1: B (X moves in the larger circle).', 1),
('6ef9828a-65e0-5128-9069-9a55a9db4ab1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 15, 15, 'An electron moves in a circle of radius 2.0 cm in a field of 1.0 mT. Calculate its speed. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '3.513e6', 'm s⁻¹', false, NULL, false, NULL, 'v = BQr/m = 1.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 0.020 ÷ 9.11 × 10⁻³¹ = 3.51 × 10⁶ m s⁻¹. Mark scheme (2 marks). C1: v = BQr/m. A1: v = 3.51 × 10⁶ m s⁻¹.', 2),
('39b97671-9cee-54c9-bab0-0e7a444444ba', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 16, 16, 'A proton and an electron move in the same magnetic field. How do their senses of rotation compare?', NULL, 1, 'multiple_choice'::answer_type, 'They circle in opposite senses', NULL, false, NULL, false, NULL, 'Opposite charges feel opposite forces for the same velocity. Mark scheme (1 mark). B1: C (They circle in opposite senses).', 1),
('d3f9c863-b4dd-5d55-aef6-8fa3edff2335', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 17, 17, 'Calculate the frequency at which an electron circles in a field of 0.10 T, in GHz, using f = BQ/2πm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '2.795 GHz', 'GHz', false, NULL, false, NULL, 'f = 0.10 × 1.60 × 10⁻¹⁹ ÷ (2π × 9.11 × 10⁻³¹) = 2.80 × 10⁹ Hz. In GHz: 2.795 × 10⁹ ÷ 10⁹ = 2.80. Mark scheme (2 marks). C1: f = BQ/2πm. A1: f = 2.80 GHz.', 2),
('983efff5-dffc-5861-a8af-3922b16a9463', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 18, 18, 'What provides the centripetal force on a charged particle moving in a circle in a uniform magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'The magnetic force on the moving charge', NULL, false, NULL, false, NULL, 'BQv acts towards the centre of the circle. Mark scheme (1 mark). B1: A (The magnetic force on the moving charge).', 1),
('bf55395f-ec2c-5cf6-8ebd-a46b0efd7579', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 19, 19, 'Calculate the flux density needed to make a proton moving at 5.0 × 10⁶ m s⁻¹ follow a circle of radius 0.50 m. Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.1044', 'T', false, NULL, false, NULL, 'B = mv/(Qr) = 1.67 × 10⁻²⁷ × 5.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 0.50) = 0.104 T. Mark scheme (2 marks). C1: rearranged r = mv/BQ. A1: B = 0.104 T.', 2),
('43334808-c2f0-5671-9e62-df523a304690', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 20, 20, 'The speed of a charged particle circling in a uniform magnetic field doubles. What happens to the radius?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'r = mv/BQ, so the radius is proportional to the speed and doubles with it. Mark scheme (1 mark). B1: D (It doubles).', 1),
('32dc79c9-da09-581b-b639-ce1f19bd75fe', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 21, 21, 'Calculate the angular speed of a proton circling in a 0.50 T field, using ω = BQ/m. Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '4.79e7', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 0.50 × 1.60 × 10⁻¹⁹ ÷ 1.67 × 10⁻²⁷ = 4.79 × 10⁷ rad s⁻¹. Mark scheme (1 mark). A1: ω = 4.79 × 10⁷ rad s⁻¹.', 1),
('d24e42c2-bfa0-5a89-ba7d-bbb7096a198d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 22, 22, 'What happens to the kinetic energy of a charged particle as it circles in a uniform magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'It stays constant', NULL, false, NULL, false, NULL, 'The magnetic force does no work. Mark scheme (1 mark). B1: B (It stays constant).', 1),
('8b4107fb-44e4-5532-b2f8-b7d4a0ea4397', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 23, 23, 'A singly charged ion of mass 3.8 × 10⁻²⁶ kg moves at 1.0 × 10⁵ m s⁻¹ at right angles to a field of 0.25 T. Calculate the radius of its path. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.095', 'm', false, NULL, false, NULL, 'r = mv/BQ = 3.8 × 10⁻²⁶ × 1.0 × 10⁵ ÷ (0.25 × 1.60 × 10⁻¹⁹) = 0.0950 m. Mark scheme (2 marks). C1: r = mv/BQ. A1: r = 0.0950 m.', 2),
('c25b9857-7a5f-5cd1-bd63-33e4ef2599ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 24, 24, 'Electrons accelerated from rest through 200 V enter a field of 1.0 mT at right angles. Calculate the radius of their path, in cm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '4.772 cm', 'cm', false, NULL, false, NULL, 'v = √(2 × 1.60 × 10⁻¹⁹ × 200 ÷ 9.11 × 10⁻³¹) = 8.38 × 10⁶ m s⁻¹. r = 9.11 × 10⁻³¹ × 8.382 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁻³) = 0.0477 m. In cm: 0.04772 × 100 = 4.77. Mark scheme (3 marks). C1: speed from eV = ½mv². C1: r = mv/BQ. A1: r = 4.77 cm.', 3),
('db34e078-2898-57e6-952f-1aeb01515b4e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 25, 25, 'A proton moves in a circle of radius 0.30 m in a 0.50 T field. Calculate its kinetic energy, in MeV (1 MeV = 1.6 × 10⁻¹³ J). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '1.078', 'MeV', false, NULL, false, NULL, 'p = BQr = 0.50 × 1.60 × 10⁻¹⁹ × 0.30 = 2.4 × 10⁻²⁰ kg m s⁻¹. E_k = p²/2m = (2.4 × 10⁻²⁰)² ÷ (2 × 1.67 × 10⁻²⁷) = 1.72 × 10⁻¹³ J. In MeV: 1.725 × 10⁻¹³ ÷ 1.6 × 10⁻¹³ = 1.08. Mark scheme (3 marks). C1: p = BQr. C1: E_k = p²/2m. A1: E_k = 1.08 MeV.', 3),
('0d9f135d-1940-50cd-a6bf-81c898032788', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 26, 26, 'Two singly charged isotopes, of masses m and 1.1m, enter the same magnetic field at the same speed. What is the ratio of their radii (heavier ÷ lighter)?', NULL, 2, 'multiple_choice'::answer_type, '1.1', NULL, false, NULL, false, NULL, 'r = mv/BQ ∝ m at the same v and Q. Mark scheme (3 marks). C1: r ∝ m. C1: ratio 1.1. A1: C (1.1).', 3),
('1d6feaf6-91d2-5d57-b553-eaccfc1d25c5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 27, 27, 'In a mass spectrometer, singly charged ions are accelerated from rest through 2000 V and enter a field of 0.20 T at right angles. An ion follows a circle of radius 0.144 m. Using m = QB²r²/2V, calculate its mass, in units of 10⁻²⁶ kg. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.318', '10⁻²⁶ kg', false, NULL, false, NULL, 'm = QB²r²/2V = 1.60 × 10⁻¹⁹ × 0.20² × 0.144² ÷ (2 × 2000) = 3.32 × 10⁻²⁶ kg. Mark scheme (4 marks). M1: m = QB²r²/2V. C1: substitution. C1: value. A1: m = 3.32 × 10⁻²⁶ kg.', 4),
('8690bb73-5f7d-50a2-a547-73cd74a05720', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 28, 28, 'An electron and a proton circle in the same magnetic field. Calculate (period of electron) ÷ (period of proton). Take mₑ = 9.11 × 10⁻³¹ kg and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '5.455e-4', NULL, false, NULL, false, NULL, 'T = 2πm/BQ ∝ m for equal |Q|: ratio = 9.11 × 10⁻³¹ ÷ 1.67 × 10⁻²⁷ = 5.46 × 10⁻⁴. Mark scheme (3 marks). C1: T ∝ m. C1: ratio. A1: ratio = 5.46 × 10⁻⁴.', 3),
('434ecbd0-336f-50ec-b99d-c9550569d8f5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 29, 29, 'Why does the time for one orbit not change when a charged particle in a uniform magnetic field speeds up?', NULL, 2, 'multiple_choice'::answer_type, 'Its radius increases in proportion to its speed, so the circumference grows at the same rate as the speed', NULL, false, NULL, false, NULL, 'T = 2πr/v = 2πm/BQ, independent of v. Mark scheme (3 marks). C1: r ∝ v. C1: T = 2πr/v constant. A1: A (Its radius increases in proportion to its speed, so the circumference grows at the same rate as the speed).', 3),
('95d06a0c-b9ea-597e-9a15-dac114107485', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 30, 30, 'A proton and an α-particle (mass 6.64 × 10⁻²⁷ kg, charge 2e) move at the same speed at right angles to the same field. Calculate (radius for α-particle) ÷ (radius for proton). Take mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '1.988', NULL, false, NULL, false, NULL, 'r ∝ m/Q: ratio = (6.64 × 10⁻²⁷ ÷ 2) ÷ 1.67 × 10⁻²⁷ = 1.99. Mark scheme (3 marks). C1: r ∝ m/Q. C1: substitution. A1: ratio = 1.99.', 3),
('fef212d0-5ed3-59b0-af0b-ea483c1b2c62', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 31, 31, 'A cyclotron has dees of radius 0.50 m in a field of 1.5 T. Calculate the maximum kinetic energy of the protons it produces, in MeV (1 MeV = 1.6 × 10⁻¹³ J). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '26.95', 'MeV', false, NULL, false, NULL, 'v_max = BQr/m = 1.5 × 1.60 × 10⁻¹⁹ × 0.50 ÷ 1.67 × 10⁻²⁷ = 7.19 × 10⁷ m s⁻¹. E_k = 0.5 × 1.67 × 10⁻²⁷ × (7.186 × 10⁷)² = 4.31 × 10⁻¹² J. In MeV: 4.311 × 10⁻¹² ÷ 1.6 × 10⁻¹³ = 26.9. Mark scheme (4 marks). C1: v = BQr/m. C1: ½mv². C1: conversion to MeV. A1: E_k = 26.9 MeV.', 4),
('6609c2d4-e079-5783-936a-431e3c8fbdcd', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 32, 32, 'In a cloud chamber in a magnetic field, a charged particle''s track is a spiral of decreasing radius. Why?', NULL, 2, 'multiple_choice'::answer_type, 'The particle loses kinetic energy by ionising the gas, so its speed and radius decrease', NULL, false, NULL, false, NULL, 'r = mv/BQ, and v falls as energy is lost in collisions. Mark scheme (3 marks). C1: energy lost to ionisation. C1: r ∝ v. A1: D (The particle loses kinetic energy by ionising the gas, so its speed and radius decrease).', 3),
('5a2365cb-f998-536f-a525-fcbc29984369', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 33, 33, 'Calculate the frequency of the alternating p.d. needed in a cyclotron to accelerate protons in a field of 1.2 T, in MHz. Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '18.3 MHz', 'MHz', false, NULL, false, NULL, 'f = BQ/2πm = 1.2 × 1.60 × 10⁻¹⁹ ÷ (2π × 1.67 × 10⁻²⁷) = 1.83 × 10⁷ Hz. In MHz: 1.830 × 10⁷ ÷ 10⁶ = 18.3. Mark scheme (3 marks). C1: f = BQ/2πm. C1: conversion. A1: f = 18.3 MHz.', 3),
('c266b91e-3295-5b97-8978-133ca5566627', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 34, 34, 'A charged particle circles with radius 1.5 cm in a uniform field. Its speed is tripled. Calculate the new radius, in cm.', NULL, 2, 'numeric'::answer_type, '4.5 cm', 'cm', false, NULL, false, NULL, 'r ∝ v, so r = 1.5 × 3 = 4.5 cm. Mark scheme (3 marks). C1: r ∝ v. C1: value. A1: r = 4.5 cm.', 3),
('f1f8c586-960d-5229-9ac5-c42ba6213f69', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 35, 35, 'A uniform magnetic field points into the page. A particle moving across the page curves clockwise. What is the sign of its charge?', NULL, 2, 'multiple_choice'::answer_type, 'Negative', NULL, false, NULL, false, NULL, 'For a positive charge, F = Qv × B with B into the page turns the path anticlockwise; clockwise means negative. Mark scheme (4 marks). C1: left-hand rule for positive charge. C1: positive gives anticlockwise. C1: so negative. A1: B (Negative).', 4),
('0e1045a3-0b9d-5649-a47e-0345bf531b0d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 36, 36, 'A charged particle moves in a circle of radius 0.020 m and completes each orbit in 1.0 × 10⁻⁷ s. Calculate its speed.', NULL, 2, 'numeric'::answer_type, '1.257e6', 'm s⁻¹', false, NULL, false, NULL, 'v = 2πr/T = 2π × 0.020 ÷ 1.0 × 10⁻⁷ = 1.26 × 10⁶ m s⁻¹. Mark scheme (3 marks). C1: v = 2πr/T. C1: substitution. A1: v = 1.26 × 10⁶ m s⁻¹.', 3),
('a4be1e0d-cca6-55be-94be-d336e1133ec3', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 37, 37, 'An electron completes one orbit in a uniform magnetic field every 3.57 × 10⁻⁹ s. Calculate the flux density, in mT. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '10.02 mT', 'mT', false, NULL, false, NULL, 'B = 2πm/(QT) = 2π × 9.11 × 10⁻³¹ ÷ (1.60 × 10⁻¹⁹ × 3.57 × 10⁻⁹) = 0.0100 T. In mT: 0.01002 × 1000 = 10.0. Mark scheme (3 marks). C1: rearranged T = 2πm/BQ. C1: conversion. A1: B = 10.0 mT.', 3),
('a2495af5-4fbf-518f-9052-adadacaf16f1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 38, 38, 'The direction of the magnetic field acting on a circling charged particle is reversed. What happens to its orbit?', NULL, 2, 'multiple_choice'::answer_type, 'It has the same radius but is traversed in the opposite sense', NULL, false, NULL, false, NULL, 'The size of BQv is unchanged; its direction reverses. Mark scheme (3 marks). C1: same |F|. C1: opposite sense. A1: C (It has the same radius but is traversed in the opposite sense).', 3),
('d1387d23-0d6a-5874-99ac-fcc2beb834d4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 39, 39, 'A deuteron (mass 2mₚ, charge e) and a proton are accelerated from rest through the same p.d. and enter the same magnetic field. Calculate (radius for deuteron) ÷ (radius for proton).', NULL, 2, 'numeric'::answer_type, '1.414', NULL, false, NULL, false, NULL, 'r = mv/BQ with v = √(2QV/m) gives r = √(2mV/Q)/B, so r ∝ √(m/Q): ratio = √2 = 1.41. Mark scheme (4 marks). M1: r = √(2mV/Q)/B. C1: r ∝ √m for equal Q. C1: ratio. A1: ratio = 1.41.', 4),
('1eda3c5e-3bd6-5f08-a295-b425fa39ff54', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 40, 40, 'An electron moves at 1.0 × 10⁶ m s⁻¹ at right angles to the Earth''s field of 5.0 × 10⁻⁵ T. Calculate the radius of its path. Take mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.1139', 'm', false, NULL, false, NULL, 'r = mv/BQ = 9.11 × 10⁻³¹ × 1.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻⁵) = 0.114 m. Mark scheme (3 marks). C1: r = mv/BQ. C1: substitution. A1: r = 0.114 m.', 3),
('ee3c980b-86e4-573a-8575-9b230750242c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 41, 41, 'Several different particles circle in the same uniform magnetic field. Which quantity is the same for all those with the same charge-to-mass ratio?', NULL, 2, 'multiple_choice'::answer_type, 'The time for one orbit', NULL, false, NULL, false, NULL, 'T = 2πm/BQ depends only on m/Q and B. Mark scheme (3 marks). C1: T depends on m/Q. C1: not on speed. A1: A (The time for one orbit).', 3),
('6bec29d6-d3a7-5f98-8d20-ad563c012b67', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 42, 42, 'Find the kinetic energy, in eV, of an electron whose path in a 1.0 mT field is a circle of radius 5.0 cm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '219.5', 'eV', false, NULL, false, NULL, 'v = BQr/m = 1.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 0.050 ÷ 9.11 × 10⁻³¹ = 8.78 × 10⁶ m s⁻¹. E_k = 0.5 × 9.11 × 10⁻³¹ × (8.782 × 10⁶)² = 3.51 × 10⁻¹⁷ J. In eV: 3.513 × 10⁻¹⁷ ÷ 1.60 × 10⁻¹⁹ = 220. Mark scheme (3 marks). C1: v = BQr/m. C1: E_k in eV. A1: E_k = 220 eV.', 3),
('4ca9384b-374a-5ec5-b04a-2adf185d93c8', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 43, 43, 'Singly charged magnesium ions of masses 3.98 × 10⁻²⁶ kg (²⁴Mg⁺) and 4.32 × 10⁻²⁶ kg (²⁶Mg⁺) are accelerated from rest through 1000 V and enter a field of 0.25 T at right angles. They travel through a semicircle to a detector. (a) Show that r = √(2mV/Q)/B. (b) Calculate the radius for each isotope. (c) Calculate the separation of the two spots on the detector, in mm. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '7.466 mm', 'mm', false, NULL, false, NULL, '(a) v = √(2QV/m) and r = mv/BQ give r = √(2mV/Q)/B. (b) r₂₄ = √(2 × 3.98 × 10⁻²⁶ × 1000 ÷ 1.60 × 10⁻¹⁹) ÷ 0.25 = 0.0892 m; r₂₆ = √(2 × 4.32 × 10⁻²⁶ × 1000 ÷ 1.60 × 10⁻¹⁹) ÷ 0.25 = 0.0930 m. (c) Separation = 2 × (0.09295 − 0.08922) = 0.00747 m. In mm: 0.007466 × 1000 = 7.47. Mark scheme (6 marks). B1: r expression derived. C1: r₂₄. C1: r₂₆. M1: separation = 2Δr. C1: conversion. A1: Δx = 7.47 mm.', 6),
('c21389f3-4776-5638-81df-885ac3968bb5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 44, 44, 'A cyclotron for protons has dees of radius 0.40 m in a field of 1.2 T. Each time a proton crosses the gap between the dees it gains 20 keV. (a) Calculate the maximum speed of the protons. (b) Calculate their maximum kinetic energy, in MeV. (c) Calculate the number of complete revolutions a proton makes. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '275.9', NULL, false, NULL, false, NULL, '(a) v = BQr/m = 1.2 × 1.60 × 10⁻¹⁹ × 0.40 ÷ 1.67 × 10⁻²⁷ = 4.60 × 10⁷ m s⁻¹. (b) E_k = 0.5 × 1.67 × 10⁻²⁷ × (4.599 × 10⁷)² = 1.77 × 10⁻¹² J, which is 11.0 MeV. (c) Two crossings per revolution give 40 keV, so n = 1.766 × 10⁻¹² ÷ (2 × 20 × 10³ × 1.60 × 10⁻¹⁹) = 276. Mark scheme (6 marks). C1: v = BQr/m. C1: ½mv². C1: conversion to MeV. M1: two gap crossings per revolution. C1: number of revolutions. A1: n = 276.', 6),
('baff7ea6-4c19-5b39-8b79-4cc9fc4eca9a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 45, 45, 'An electron track in a field of 2.0 mT has a radius of 5.0 cm at first and 3.0 cm later, after the electron has lost energy. (a) Show that the kinetic energy is (BQr)²/2m. (b) Calculate the initial kinetic energy, in eV. (c) Calculate the energy lost, in eV. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '562', 'eV', false, NULL, false, NULL, '(a) p = mv = BQr, so E_k = p²/2m = (BQr)²/2m. (b) E₁ = (2.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 0.050)² ÷ (2 × 9.11 × 10⁻³¹) = 1.41 × 10⁻¹⁶ J, which is 878 eV. (c) E ∝ r², so E₂ = 0.36E₁ and the loss = 0.64 × 878.2 = 562 eV. Mark scheme (5 marks). B1: E_k = (BQr)²/2m. C1: initial energy. C1: E ∝ r². C1: energy lost. A1: ΔE = 562 eV.', 5),
('a423a0a7-d890-5e2e-87ee-5fcf643855c2', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 46, 46, 'Electrons moving at 2.0 × 10⁷ m s⁻¹ enter a region 2.0 cm wide containing a uniform field of 2.0 mT at right angles to their motion. (a) Calculate the radius of their circular path in the field. (b) Show that the angle θ through which they are deflected satisfies sin θ = (width)/r. (c) Calculate θ. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '20.56', '°', false, NULL, false, NULL, '(a) r = 9.11 × 10⁻³¹ × 2.0 × 10⁷ ÷ (1.60 × 10⁻¹⁹ × 2.0 × 10⁻³) = 0.0569 m. (b) The electron follows an arc of radius r; geometry of the arc across width d gives sin θ = d/r. (c) sin θ = 0.020 ÷ 0.05694 = 0.3513, so θ = sin⁻¹ 0.3513 = 20.6°. Mark scheme (6 marks). C1: r = mv/BQ. B1: geometry sin θ = d/r. C1: sin θ value. C1: θ. B1: speed unchanged. A1: θ = 20.6°.', 6),
('adcce1ad-b6ba-5fef-933c-81db72069f41', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 47, 47, '(a) Show that the period of a charged particle in a uniform magnetic field is T = 2πm/BQ and is independent of its speed. (b) Calculate the period of a deuteron (mass 3.34 × 10⁻²⁷ kg, charge e) in a field of 1.5 T, in ns. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '87.44 ns', 'ns', false, NULL, false, NULL, '(a) T = 2πr/v and r = mv/BQ, so T = 2πm/BQ: v cancels. (b) T = 2π × 3.34 × 10⁻²⁷ ÷ (1.5 × 1.60 × 10⁻¹⁹) = 8.74 × 10⁻⁸ s. In ns: 8.744 × 10⁻⁸ × 10⁹ = 87.4. Mark scheme (5 marks). M1: T = 2πr/v. B1: v cancels. C1: substitution. C1: conversion. A1: T = 87.4 ns.', 5),
('5604dccc-b91f-570a-aecb-31067eabc1b7', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 48, 48, 'In a fine-beam tube, electrons are accelerated through different p.d.s V and circle in a fixed field of 1.0 mT. Results: V/V = 100, 200, 300, 400 and r/cm = 3.37, 4.77, 5.84, 6.74. (a) Show that r² = 2mV/(eB²). (b) Calculate the gradient of a graph of r² against V using the first and last points. (c) Calculate e/m, in units of 10¹¹ C kg⁻¹. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.761', '10¹¹ C kg⁻¹', false, NULL, false, NULL, '(a) r = √(2mV/e)/B, so r² = 2mV/(eB²). (b) Gradient = (0.0674² − 0.0337²) ÷ (400 − 100) = 1.14 × 10⁻⁵ m² V⁻¹. (c) e/m = 2 ÷ (B² × gradient) = 2 ÷ ((1.0 × 10⁻³)² × 1.136 × 10⁻⁵) = 1.76 × 10¹¹ C kg⁻¹. Mark scheme (6 marks). B1: r² expression. C1: r in m. C1: gradient. M1: e/m = 2/(B² × gradient). C1: value. A1: e/m = 1.76 × 10¹¹ C kg⁻¹.', 6),
('02de7cd1-ca76-5d28-8745-46582b9b9257', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 49, 49, 'A proton from the solar wind moves at 4.0 × 10⁵ m s⁻¹ at right angles to the Earth''s field of 3.0 × 10⁻⁵ T. (a) Calculate the radius of its circular path. (b) Calculate its period, in ms. (c) Explain why this traps the proton near the Earth. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '2.186 ms', 'ms', false, NULL, false, NULL, '(a) r = 1.67 × 10⁻²⁷ × 4.0 × 10⁵ ÷ (1.60 × 10⁻¹⁹ × 3.0 × 10⁻⁵) = 139 m. (b) T = 2π × 1.67 × 10⁻²⁷ ÷ (1.60 × 10⁻¹⁹ × 3.0 × 10⁻⁵) = 0.00219 s. In ms: 0.002186 × 1000 = 2.19. (c) It circles about the field lines instead of travelling straight on, so it stays in the magnetosphere. Mark scheme (5 marks). C1: r = mv/BQ. C1: T = 2πm/BQ. C1: conversion. B1: trapped circling field lines. A1: T = 2.19 ms.', 5),
('86599d89-1ab6-5407-910a-07220cbbdc65', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 50, 50, 'An electron and a positron, each with a kinetic energy of 1.0 keV, move at right angles to a field of 1.0 mT. (a) Show that r = √(2mE_k)/(eB). (b) Calculate the radius of each path, in cm. (c) Explain how their tracks differ. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '10.67 cm', 'cm', false, NULL, false, NULL, '(a) p = √(2mE_k) and r = p/(eB). (b) E_k = 1.0 × 10³ × 1.60 × 10⁻¹⁹ = 1.6 × 10⁻¹⁶ J; r = √(2 × 9.11 × 10⁻³¹ × 1.6 × 10⁻¹⁶) ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁻³) = 0.107 m. In cm: 0.1067 × 100 = 10.7. (c) Same radius, but they curve in opposite senses because their charges are opposite. Mark scheme (6 marks). B1: r from momentum. C1: keV to J. C1: radius. C1: conversion. B1: opposite curvature. A1: r = 10.7 cm.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('7dcd64c0-8d66-57f2-8498-c13b3ef6182b', '92193abf-512c-5ad8-b6fd-cca4734fe48e', 'By equating BQv to mg', 'A', false, 0),
('97810554-032f-5e60-bdd4-9a2c4f2b8807', '92193abf-512c-5ad8-b6fd-cca4734fe48e', 'By equating BQv to ½mv²', 'B', false, 1),
('9cee4a17-1e5a-5518-8d3f-046a97e83e2e', '92193abf-512c-5ad8-b6fd-cca4734fe48e', 'By equating the magnetic force BQv to the centripetal force mv²/r', 'C', true, 2),
('f8ff537d-9dab-5373-9aa6-1613ecaadad7', '92193abf-512c-5ad8-b6fd-cca4734fe48e', 'By equating BQ to mv', 'D', false, 3),
('05f9f4a8-43eb-5c38-b811-7be58855da59', 'aab60ce3-8526-5108-96d0-ea8a5d86e6ec', 'It halves', 'A', true, 0),
('5eba8af1-2657-553b-8502-dc86c0cba4a8', 'aab60ce3-8526-5108-96d0-ea8a5d86e6ec', 'It doubles', 'B', false, 1),
('db0e8c9f-fd62-5961-80d3-7f4a7d853e59', 'aab60ce3-8526-5108-96d0-ea8a5d86e6ec', 'It stays the same', 'C', false, 2),
('dffb2057-d4ce-5dd2-8e92-720d7b0450f8', 'aab60ce3-8526-5108-96d0-ea8a5d86e6ec', 'It quadruples', 'D', false, 3),
('6e558860-5549-5e50-a7ca-55369b641b8f', '2e43f98b-90d1-5209-a7f1-54f0d22509a6', 'It is proportional to the speed', 'A', false, 0),
('1407322b-0456-50ff-a30e-d6667acd046d', '2e43f98b-90d1-5209-a7f1-54f0d22509a6', 'It is inversely proportional to the speed', 'B', false, 1),
('a6235ca9-f445-5275-ad80-a53251aec6d9', '2e43f98b-90d1-5209-a7f1-54f0d22509a6', 'It is proportional to the speed squared', 'C', false, 2),
('261a553c-433c-5f9e-84ab-e36a13f208a3', '2e43f98b-90d1-5209-a7f1-54f0d22509a6', 'It does not depend on the speed', 'D', true, 3),
