('14bd6708-938b-5024-adfd-725367f1bb9f', '32f8c1c7-65d9-5615-9b36-e04483e9ccaa', 'X moves in the larger circle', 'B', true, 1),
('0116878b-9c24-549f-833b-41f63b6f07e1', '32f8c1c7-65d9-5615-9b36-e04483e9ccaa', 'They move in circles of equal size', 'C', false, 2),
('b52b7b19-b505-58f3-9314-6853687f89ac', '32f8c1c7-65d9-5615-9b36-e04483e9ccaa', 'X is not deflected', 'D', false, 3),
('5b20c5f0-2afc-58de-bd5e-6453aca63700', '39b97671-9cee-54c9-bab0-0e7a444444ba', 'They circle in the same sense', 'A', false, 0),
('25453e87-4169-5c83-8210-8295b6fea6d6', '39b97671-9cee-54c9-bab0-0e7a444444ba', 'Only the proton circles', 'B', false, 1),
('8d2daf36-a39a-5415-a79f-4612f6c5884d', '39b97671-9cee-54c9-bab0-0e7a444444ba', 'They circle in opposite senses', 'C', true, 2),
('7d147d1d-7ea2-5f60-871c-0b806fdf2f5c', '39b97671-9cee-54c9-bab0-0e7a444444ba', 'Only the electron circles', 'D', false, 3),
('cea9b555-40f6-5325-87b7-7b2f4c48b01e', '983efff5-dffc-5861-a8af-3922b16a9463', 'The magnetic force on the moving charge', 'A', true, 0),
('1485aeb5-fe27-5862-905f-2a4b5c1c6afd', '983efff5-dffc-5861-a8af-3922b16a9463', 'Its weight', 'B', false, 1),
('4e8a7d7f-9387-5115-ad72-1461df500aed', '983efff5-dffc-5861-a8af-3922b16a9463', 'An electric field', 'C', false, 2),
('b2928b77-bfb4-5336-b50b-1fae3bcbe910', '983efff5-dffc-5861-a8af-3922b16a9463', 'The particle''s own inertia', 'D', false, 3),
