('bd7bef6f-6160-5886-b614-70bfc51a4e7c', '43334808-c2f0-5671-9e62-df523a304690', 'It quadruples', 'C', false, 2),
('67aff753-8041-540a-ac25-798201fe40c1', '43334808-c2f0-5671-9e62-df523a304690', 'It doubles', 'D', true, 3),
