('c3b14b94-d490-5cc8-911e-817bb723095d', 'd24e42c2-bfa0-5a89-ba7d-bbb7096a198d', 'It stays constant', 'B', true, 1),
('fed11d29-9486-5d5b-95e1-c0c9b3f078e7', 'd24e42c2-bfa0-5a89-ba7d-bbb7096a198d', 'It decreases each orbit', 'C', false, 2),
('7f654ae3-d234-528e-acf5-7ddd357a73c5', 'd24e42c2-bfa0-5a89-ba7d-bbb7096a198d', 'It is zero', 'D', false, 3),
