('72b586c9-c9da-53be-8249-45d938f64bc3', '434ecbd0-336f-50ec-b99d-c9550569d8f5', 'Its radius increases in proportion to its speed, so the circumference grows at the same rate as the speed', 'A', true, 0),
('d2384df5-7fc0-5301-8673-d21f12d53c8f', '434ecbd0-336f-50ec-b99d-c9550569d8f5', 'Its speed cannot change in a magnetic field', 'B', false, 1),
('f1ca2e6e-b329-5d9a-b4ea-5cb750bd1304', '434ecbd0-336f-50ec-b99d-c9550569d8f5', 'The field gets weaker as the particle speeds up', 'C', false, 2),
('8c1cd8a8-010a-5654-b557-09c74d4347f1', '434ecbd0-336f-50ec-b99d-c9550569d8f5', 'Its mass decreases as it speeds up', 'D', false, 3),
('5b819707-6143-5896-bc46-ef571161b71f', '6609c2d4-e079-5783-936a-431e3c8fbdcd', 'The magnetic field is getting stronger', 'A', false, 0),
('0d5310fe-d842-5e62-8284-a52d24b52f23', '6609c2d4-e079-5783-936a-431e3c8fbdcd', 'The particle is gaining charge', 'B', false, 1),
('ac8f3c60-9461-53fb-916d-720929f06f22', '6609c2d4-e079-5783-936a-431e3c8fbdcd', 'The magnetic force does work on it', 'C', false, 2),
