('720ff3c2-a29d-5475-bab1-24a69cf1c6ab', 'a2495af5-4fbf-518f-9052-adadacaf16f1', 'It becomes a straight line', 'B', false, 1),
('467055f9-2d4b-5549-be75-aee4e37d3975', 'a2495af5-4fbf-518f-9052-adadacaf16f1', 'It has the same radius but is traversed in the opposite sense', 'C', true, 2),
