INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('baed2b73-c3f1-5048-9bb1-ce36ed12c6be', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 7, 7, 'Ions pass straight through crossed fields of 6.0 × 10⁴ V m⁻¹ and 0.020 T. How fast are they moving?', NULL, 1, 'numeric'::answer_type, '3e6', 'm s⁻¹', false, NULL, false, NULL, 'v = E/B = 6.0 × 10⁴ ÷ 0.020 = 3.0 × 10⁶ m s⁻¹. Mark scheme (2 marks). C1: v = E/B. A1: v = 3.0 × 10⁶ m s⁻¹.', 2),
('e7c8682c-445a-556f-a6bf-5b99f62e125f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 8, 8, 'In a velocity selector, what condition must be met for a charged particle to pass through undeflected?', NULL, 1, 'multiple_choice'::answer_type, 'The electric force EQ equals the magnetic force BQv and acts in the opposite direction', NULL, false, NULL, false, NULL, 'EQ = BQv gives v = E/B. Mark scheme (1 mark). B1: C (The electric force EQ equals the magnetic force BQv and acts in the opposite direction).', 1),
('a64a0596-2c51-5daf-b92f-b6d5d00d489e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 9, 9, 'Two parallel plates 5.0 mm apart have a p.d. of 300 V. Calculate the electric field between them.', NULL, 1, 'numeric'::answer_type, '60000', 'V m⁻¹', false, NULL, false, NULL, 'E = V/d = 300 ÷ 5.0 × 10⁻³ = 6.0 × 10⁴ V m⁻¹. Mark scheme (2 marks). C1: E = V/d. A1: E = 6.0 × 10⁴ V m⁻¹.', 2),
('e8105bb7-a289-58da-b3cb-79aeae02221f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 10, 10, 'How are the electric field, the magnetic field and the particle velocity arranged in a velocity selector?', NULL, 1, 'multiple_choice'::answer_type, 'All three are mutually at right angles', NULL, false, NULL, false, NULL, 'Only then can the two forces be equal and opposite and both perpendicular to v. Mark scheme (1 mark). B1: A (All three are mutually at right angles).', 1),
('62ea8523-98ff-52eb-aebb-33e652cd79c4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 11, 11, 'A velocity selector uses an electric field of 2.0 × 10⁴ V m⁻¹ to select ions moving at 4.0 × 10⁵ m s⁻¹. Calculate the magnetic flux density needed.', NULL, 1, 'numeric'::answer_type, '0.05', 'T', false, NULL, false, NULL, 'B = E/v = 2.0 × 10⁴ ÷ 4.0 × 10⁵ = 0.050 T. Mark scheme (2 marks). C1: B = E/v. A1: B = 0.050 T.', 2),
('e3aa2736-1e28-503e-a50d-710e3819396a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 12, 12, 'In a velocity selector, how are particles slower than E/B deflected?', NULL, 1, 'multiple_choice'::answer_type, 'In the direction of the electric force', NULL, false, NULL, false, NULL, 'For slower particles BQv < EQ, so the electric force wins. Mark scheme (1 mark). B1: D (In the direction of the electric force).', 1),
('4737f1ab-ae59-5085-9130-0059bb4919e1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 13, 13, 'Calculate the electric force on an electron in a field of 5.0 × 10⁴ V m⁻¹, in units of 10⁻¹⁵ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8', '10⁻¹⁵ N', false, NULL, false, NULL, 'F = eE = 1.60 × 10⁻¹⁹ × 5.0 × 10⁴ = 8.00 × 10⁻¹⁵ N. Mark scheme (2 marks). C1: F = eE. A1: F = 8.0 × 10⁻¹⁵ N.', 2),
('3e54ab45-e4b1-5165-a6b4-93c141f90b84', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 14, 14, 'Both the electric field and the magnetic field in a velocity selector are reversed. What happens to the speed selected?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'Both forces reverse, so they still balance at v = E/B. Mark scheme (1 mark). B1: B (It stays the same).', 1),
('3ba523fb-cad3-555f-b833-8d4f5b9dea25', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 15, 15, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at right angles to a field of 0.025 T. Calculate the magnetic force on it, in units of 10⁻¹⁵ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8', '10⁻¹⁵ N', false, NULL, false, NULL, 'F = BQv = 0.025 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁶ = 8.00 × 10⁻¹⁵ N. Mark scheme (2 marks). C1: F = BQv. A1: F = 8.0 × 10⁻¹⁵ N.', 2),
('2798c098-e838-5aa5-9615-1bdfaf7ea255', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 16, 16, 'A velocity selector is set for positive ions. Negative ions of the same speed are sent through instead. What happens to them?', NULL, 1, 'multiple_choice'::answer_type, 'They also pass through undeflected', NULL, false, NULL, false, NULL, 'Both forces reverse together, so they still balance. Mark scheme (1 mark). B1: C (They also pass through undeflected).', 1),
('e0f650c3-f06f-56d6-aec9-e360b09db399', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 17, 17, 'Calculate the p.d. needed across plates 8.0 mm apart so that a velocity selector with B = 0.040 T selects ions of speed 5.0 × 10⁵ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '160', 'V', false, NULL, false, NULL, 'E = Bv = 0.040 × 5.0 × 10⁵ = 2.0 × 10⁴ V m⁻¹. V = Ed = 2.0 × 10⁴ × 8.0 × 10⁻³ = 160 V. Mark scheme (2 marks). C1: E = Bv then V = Ed. A1: V = 160 V.', 2),
('6b31872c-00bc-5336-b19c-ab1fe9f1ac18', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 18, 18, 'In a velocity selector, which force acts on a charged particle even when it is not moving?', NULL, 1, 'multiple_choice'::answer_type, 'The electric force', NULL, false, NULL, false, NULL, 'F = EQ needs no motion; F = BQv is zero when v = 0. Mark scheme (1 mark). B1: A (The electric force).', 1),
('b1b064cc-6591-5c32-bc1f-3c2049f55423', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 19, 19, 'Calculate E/B for E = 1.0 × 10³ V m⁻¹ and B = 1.0 × 10⁻³ T.', NULL, 1, 'numeric'::answer_type, '1e6', 'm s⁻¹', false, NULL, false, NULL, 'E/B = 1.0 × 10³ ÷ 1.0 × 10⁻³ = 1.0 × 10⁶ m s⁻¹. Mark scheme (1 mark). A1: v = 1.0 × 10⁶ m s⁻¹.', 1),
('07d5a649-b1ac-56a4-83f7-43227625ac77', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 20, 20, 'How do the electric and magnetic forces on a charged particle depend on its speed?', NULL, 1, 'multiple_choice'::answer_type, 'The electric force does not depend on speed; the magnetic force is proportional to speed', NULL, false, NULL, false, NULL, 'F_E = EQ; F_B = BQv. Mark scheme (1 mark). B1: D (The electric force does not depend on speed; the magnetic force is proportional to speed).', 1),
('a0e46ec8-24e1-5526-96ce-0bf4f7f49824', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 21, 21, 'A particle moves through a velocity selector at twice the selected speed. Calculate (magnetic force) ÷ (electric force).', NULL, 1, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'At the selected speed BQv = EQ. For example, with E = 1.0 × 10⁴ V m⁻¹ and B = 0.010 T the selected speed is 1.0 × 10⁶ m s⁻¹; at 2.0 × 10⁶ m s⁻¹, F_B ÷ F_E = 0.010 × 2.0 × 10⁶ ÷ 1.0 × 10⁴ = 2.0. Mark scheme (2 marks). C1: F_B ∝ v. A1: ratio = 2.0.', 2),
('0b864fda-5e3a-5616-a6a4-58340c986692', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 22, 22, 'The plate separation in a velocity selector is doubled, with the same p.d. and magnetic field. What happens to the speed selected?', NULL, 1, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'E = V/d halves, so v = E/B halves. Mark scheme (1 mark). B1: B (It halves).', 1),
('5dc49a12-f006-52e4-b588-ea13a6e325ed', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 23, 23, 'A velocity selector has E = 2.0 × 10⁵ V m⁻¹ and B = 0.40 T. Calculate the kinetic energy of the protons it selects, in keV. Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.305', 'keV', false, NULL, false, NULL, 'v = E/B = 2.0 × 10⁵ ÷ 0.40 = 5.0 × 10⁵ m s⁻¹. E_k = 0.5 × 1.67 × 10⁻²⁷ × (5.0 × 10⁵)² = 2.09 × 10⁻¹⁶ J. In keV: 2.088 × 10⁻¹⁶ ÷ 1.6 × 10⁻¹⁶ = 1.30. Mark scheme (2 marks). C1: v = E/B then ½mv². A1: E_k = 1.30 keV.', 2),
('9bfd83bc-4210-52a0-91f4-cb0035343ffc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 24, 24, 'A velocity selector has plates 10 mm apart with a p.d. of 500 V and a magnetic field of 0.10 T. Calculate the speed selected.', NULL, 2, 'numeric'::answer_type, '5e5', 'm s⁻¹', false, NULL, false, NULL, 'E = 500 ÷ 0.010 = 5.0 × 10⁴ V m⁻¹. v = E/B = 5.0 × 10⁴ ÷ 0.10 = 5.0 × 10⁵ m s⁻¹. Mark scheme (3 marks). C1: E = V/d. C1: v = E/B. A1: v = 5.0 × 10⁵ m s⁻¹.', 3),
('8846830c-70de-5b0e-9cec-2fadb2f951b0', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 25, 25, 'Electrons accelerated from rest through 2.0 kV enter crossed fields with B = 1.0 mT. The plates are 1.0 cm apart. Calculate the p.d. across the plates needed for the electrons to pass undeflected. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '265.1', 'V', false, NULL, false, NULL, 'v = √(2 × 1.60 × 10⁻¹⁹ × 2000 ÷ 9.11 × 10⁻³¹) = 2.65 × 10⁷ m s⁻¹. E = Bv = 1.0 × 10⁻³ × 2.651 × 10⁷ = 2.65 × 10⁴ V m⁻¹. V = Ed = 2.651 × 10⁴ × 0.010 = 265 V. Mark scheme (4 marks). C1: speed. C1: E = Bv. C1: V = Ed. A1: V = 265 V.', 4),
('5c541216-c892-5d12-a29a-68bae8dbbc5d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 26, 26, 'A beam contains protons and α-particles all moving at the speed E/B selected by a velocity selector. Which particles pass through undeflected?', NULL, 2, 'multiple_choice'::answer_type, 'Both the protons and the α-particles', NULL, false, NULL, false, NULL, 'v = E/B does not depend on charge or mass. Mark scheme (3 marks). C1: EQ = BQv. C1: Q cancels. A1: C (Both the protons and the α-particles).', 3),
('9589ad63-ddc2-543f-97eb-159d9d3f6446', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 27, 27, 'A selector has E = 3.0 × 10⁴ V m⁻¹ and B = 0.10 T. A proton enters at 4.5 × 10⁵ m s⁻¹. Calculate the resultant force on it, in units of 10⁻¹⁵ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.4', '10⁻¹⁵ N', false, NULL, false, NULL, 'F_B = 0.10 × 1.60 × 10⁻¹⁹ × 4.5 × 10⁵ = 7.2 × 10⁻¹⁵ N. F_E = 1.60 × 10⁻¹⁹ × 3.0 × 10⁴ = 4.8 × 10⁻¹⁵ N. Resultant = 7.2 × 10⁻¹⁵ − 4.8 × 10⁻¹⁵ = 2.40 × 10⁻¹⁵ N, in the direction of the magnetic force. Mark scheme (3 marks). C1: both forces. C1: difference. A1: F = 2.4 × 10⁻¹⁵ N.', 3),
('363bacba-118b-5702-b32f-753c025338c8', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 28, 28, 'Electrons move at 1.5 × 10⁷ m s⁻¹ through a velocity selector 5.0 cm long. Calculate the time each spends in the selector, in ns.', NULL, 2, 'numeric'::answer_type, '3.333 ns', 'ns', false, NULL, false, NULL, 't = L/v = 0.050 ÷ 1.5 × 10⁷ = 3.33 × 10⁻⁹ s. In ns: 3.333 × 10⁻⁹ × 10⁹ = 3.33. Mark scheme (3 marks). C1: t = L/v. C1: conversion. A1: t = 3.33 ns.', 3),
('ac2a6a68-2258-55bb-ad64-45bc2f661b62', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 29, 29, 'A particle slower than the selected speed enters a velocity selector. Which describes its path?', NULL, 2, 'multiple_choice'::answer_type, 'It curves towards the side of the electric force', NULL, false, NULL, false, NULL, 'For v < E/B, EQ > BQv. Mark scheme (3 marks). C1: EQ > BQv. C1: deflected with electric force. A1: A (It curves towards the side of the electric force).', 3),
('c6fd99f6-524b-5fc8-af06-17be1c5826e7', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 30, 30, 'In a mass spectrometer, ions selected at 2.0 × 10⁵ m s⁻¹ enter a second field of 0.50 T. An ion has mass 3.9 × 10⁻²⁶ kg and charge e. Calculate the radius of its path. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.0975', 'm', false, NULL, false, NULL, 'r = mv/BQ = 3.9 × 10⁻²⁶ × 2.0 × 10⁵ ÷ (0.50 × 1.60 × 10⁻¹⁹) = 0.0975 m. Mark scheme (3 marks). C1: r = mv/BQ. C1: substitution. A1: r = 0.0975 m.', 3),
('d216a42f-9c58-50d4-a1a0-8a0740de3dea', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 31, 31, 'In a Bainbridge mass spectrometer, a selector with E = 1.0 × 10⁴ V m⁻¹ and B₁ = 0.050 T is followed by a field B₂ = 0.050 T. Singly charged ions follow a circle of radius 0.083 m. Calculate the mass of an ion, in units of 10⁻²⁷ kg. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.32', '10⁻²⁷ kg', false, NULL, false, NULL, 'v = E/B₁ = 1.0 × 10⁴ ÷ 0.050 = 2.0 × 10⁵ m s⁻¹. m = QB₂r/v = 1.60 × 10⁻¹⁹ × 0.050 × 0.083 ÷ 2.0 × 10⁵ = 3.32 × 10⁻²⁷ kg. Mark scheme (4 marks). C1: v = E/B₁. M1: m = QB₂r/v. C1: value. A1: m = 3.32 × 10⁻²⁷ kg.', 4),
('3d762e45-665e-5d8b-9e85-e614927424aa', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 32, 32, 'Both E and B in a velocity selector are doubled. What happens to the speed of the particles that pass through?', NULL, 2, 'multiple_choice'::answer_type, 'It is unchanged', NULL, false, NULL, false, NULL, 'v = E/B; doubling both leaves the ratio unchanged, though the forces are larger. Mark scheme (4 marks). C1: v = E/B. C1: ratio unchanged. C1: forces larger but balanced. A1: D (It is unchanged).', 4),
('5af89d3d-7597-550d-9369-117d96765f9e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 33, 33, 'An electron moving at 1.0 × 10⁷ m s⁻¹ passes between plates 4.0 cm long where the electric field is 2.0 × 10³ V m⁻¹ (no magnetic field). Calculate its sideways deflection, in mm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '2.81 mm', 'mm', false, NULL, false, NULL, 'a = eE/m = 1.60 × 10⁻¹⁹ × 2.0 × 10³ ÷ 9.11 × 10⁻³¹ = 3.51 × 10¹⁴ m s⁻². t = 0.040 ÷ 1.0 × 10⁷ = 4.0 × 10⁻⁹ s. y = ½at² = 0.5 × 3.513 × 10¹⁴ × (4.0 × 10⁻⁹)² = 0.00281 m. In mm: 0.002810 × 1000 = 2.81. Mark scheme (3 marks). C1: a and t. C1: y = ½at². A1: y = 2.81 mm.', 3),
('c8d85595-6cd6-560a-b3dc-be36a269e831', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 34, 34, 'Calculate the magnetic flux density needed to cancel the deflection of an electron moving at 1.0 × 10⁷ m s⁻¹ through an electric field of 2.0 × 10³ V m⁻¹, in µT.', NULL, 2, 'numeric'::answer_type, '200 uT', 'µT', false, NULL, false, NULL, 'B = E/v = 2.0 × 10³ ÷ 1.0 × 10⁷ = 2.0 × 10⁻⁴ T. In µT: 2.0 × 10⁻⁴ × 10⁶ = 200. Mark scheme (3 marks). C1: B = E/v. C1: conversion. A1: B = 200 µT.', 3),
('29844196-6884-5d11-b63c-c0e5c96abc34', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 35, 35, 'In a velocity selector, which field does work on a particle that is being deflected?', NULL, 2, 'multiple_choice'::answer_type, 'Only the electric field', NULL, false, NULL, false, NULL, 'The magnetic force is perpendicular to the velocity; the electric force can have a component along the motion. Mark scheme (3 marks). C1: magnetic force perpendicular. C1: electric force can do work. A1: B (Only the electric field).', 3),
('3efe37f7-2f30-5d97-b34a-581035f09b9b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 36, 36, 'Electrons pass undeflected through crossed fields of 3.0 × 10⁴ V m⁻¹ and 1.5 mT. The electric field is then switched off. Calculate the radius of their path in the magnetic field, in cm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '7.592 cm', 'cm', false, NULL, false, NULL, 'v = E/B = 3.0 × 10⁴ ÷ 1.5 × 10⁻³ = 2.0 × 10⁷ m s⁻¹. r = mv/BQ = 9.11 × 10⁻³¹ × 2.0 × 10⁷ ÷ (1.5 × 10⁻³ × 1.60 × 10⁻¹⁹) = 0.0759 m. In cm: 0.07592 × 100 = 7.59. Mark scheme (4 marks). C1: v = E/B. C1: r = mv/BQ. C1: conversion. A1: r = 7.59 cm.', 4),
('e730f1b0-d6d9-56c8-9078-79683a241bdf', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 37, 37, 'In a selector, the top plate is positive, so the electric field points down the page. Positive ions move from left to right. Which magnetic field direction makes the magnetic force balance the electric force?', NULL, 2, 'multiple_choice'::answer_type, 'Into the page', NULL, false, NULL, false, NULL, 'The electric force is downwards, so the magnetic force must be upwards: left-hand rule with current to the right and thumb up gives a field into the page. Mark scheme (3 marks). C1: magnetic force must be upwards. C1: left-hand rule. A1: C (Into the page).', 3),
('6955263e-1a6b-5872-b3e0-fba1342a0a88', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 38, 38, 'Electrons emerge undeflected from crossed fields of 1.0 × 10⁴ V m⁻¹ and 2.0 × 10⁻³ T. What kinetic energy, in eV, do they have? Take mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '71.17', 'eV', false, NULL, false, NULL, 'v = E/B = 1.0 × 10⁴ ÷ 2.0 × 10⁻³ = 5.0 × 10⁶ m s⁻¹. E_k = 0.5 × 9.11 × 10⁻³¹ × (5.0 × 10⁶)² = 1.14 × 10⁻¹⁷ J. In eV: 1.139 × 10⁻¹⁷ ÷ 1.60 × 10⁻¹⁹ = 71.2. Mark scheme (3 marks). C1: v = E/B. C1: E_k in eV. A1: E_k = 71.2 eV.', 3),
('98f8e80b-329b-5aaf-8762-cfdab083e09c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 39, 39, 'A selector uses B = 0.30 T and plates 2.0 cm apart. Calculate the p.d. needed to select particles moving at 2.0 × 10⁵ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1200', 'V', false, NULL, false, NULL, 'V = Ed = Bvd = 0.30 × 2.0 × 10⁵ × 0.020 = 1200 V. Mark scheme (3 marks). C1: E = Bv. C1: V = Ed. A1: V = 1200 V.', 3),
('4d0c566d-4616-56d2-a5c8-32c3a660d150', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 40, 40, 'For a particle moving faster than E/B through a velocity selector, which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The magnetic force is larger than the electric force', NULL, false, NULL, false, NULL, 'BQv grows with v; EQ does not. Mark scheme (3 marks). C1: F_B ∝ v. C1: F_B > F_E. A1: A (The magnetic force is larger than the electric force).', 3),
('f70ccd75-1e3d-535d-8405-be043535d908', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 41, 41, 'In a velocity selector, E = 4.0 × 10⁴ V m⁻¹ with an uncertainty of ±2 % and B = 0.080 T with an uncertainty of ±1 %. Calculate the percentage uncertainty in the selected speed.', NULL, 2, 'numeric'::answer_type, '3', '%', false, NULL, false, NULL, 'v = E/B, so the percentage uncertainties add: 2 + 1 = 3.0 %. Mark scheme (4 marks). M1: quotient rule. C1: add percentages. C1: value. A1: uncertainty = 3.0%.', 4),
('a89b7e0c-1d3f-5acc-b4d9-bb1a921e0722', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 42, 42, 'A velocity selector with B = 0.010 T must select particles moving at 1.0 % of the speed of light. Calculate the electric field needed. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '30000', 'V m⁻¹', false, NULL, false, NULL, 'v = 0.010 × 3.00 × 10⁸ = 3.0 × 10⁶ m s⁻¹. E = Bv = 0.010 × 3.0 × 10⁶ = 3.0 × 10⁴ V m⁻¹. Mark scheme (3 marks). C1: v. C1: E = Bv. A1: E = 3.0 × 10⁴ V m⁻¹.', 3),
('911f6bd1-fea5-54c2-8300-d383750f805d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 43, 43, 'Electrons accelerated through 2.5 kV pass undeflected between plates 1.5 cm apart with a p.d. of 450 V, in a magnetic field of 1.0 mT. (a) Calculate the electric field. (b) Calculate the speed of the electrons from the crossed fields. (c) Check this speed using the accelerating p.d. and e/m = 1.76 × 10¹¹ C kg⁻¹. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3e7', 'm s⁻¹', false, NULL, false, NULL, '(a) E = 450 ÷ 0.015 = 3.0 × 10⁴ V m⁻¹. (b) v = E/B = 3.0 × 10⁴ ÷ 1.0 × 10⁻³ = 3.0 × 10⁷ m s⁻¹. (c) v = √(2(e/m)V) = √(2 × 1.76 × 10¹¹ × 2500) = 2.97 × 10⁷ m s⁻¹, in good agreement. Mark scheme (6 marks). C1: E = V/d. M1: EQ = BQv. C1: v = E/B. C1: speed from energy. B1: agreement. A1: v = 3.0 × 10⁷ m s⁻¹.', 6),
('09e88407-e6f1-5fb8-a26c-936b04ba80a9', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 44, 44, 'Singly charged ²⁰Ne⁺ and ²²Ne⁺ ions (masses 3.32 × 10⁻²⁶ kg and 3.65 × 10⁻²⁶ kg) pass through a velocity selector with E = 2.0 × 10⁴ V m⁻¹ and B₁ = 0.10 T, then enter a field B₂ = 0.20 T and travel through a semicircle. (a) Calculate the speed of the ions leaving the selector. (b) Calculate the radius for each isotope. (c) Calculate the separation of the two images, in cm. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '4.125 cm', 'cm', false, NULL, false, NULL, '(a) v = 2.0 × 10⁴ ÷ 0.10 = 2.0 × 10⁵ m s⁻¹. (b) r₂₀ = 3.32 × 10⁻²⁶ × 2.0 × 10⁵ ÷ (1.60 × 10⁻¹⁹ × 0.20) = 0.208 m; r₂₂ = 3.65 × 10⁻²⁶ × 2.0 × 10⁵ ÷ (1.60 × 10⁻¹⁹ × 0.20) = 0.228 m. (c) Separation = 2 × (0.2281 − 0.2075) = 0.0413 m. In cm: 0.04125 × 100 = 4.12. Mark scheme (6 marks). C1: v = E/B₁. C1: r₂₀. C1: r₂₂. M1: separation = 2Δr. C1: conversion. A1: Δx = 4.13 cm.', 6),
('a50abda8-46e6-547e-aa3f-dae83f3e5d70', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 45, 45, 'A velocity selector has E = 1.5 × 10⁴ V m⁻¹ and B = 0.050 T. A proton enters at 2.0 × 10⁵ m s⁻¹. (a) Calculate the selected speed. (b) Calculate the resultant force on the proton, in units of 10⁻¹⁶ N. (c) State the direction of the resultant force. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '8', '10⁻¹⁶ N', false, NULL, false, NULL, '(a) v = 1.5 × 10⁴ ÷ 0.050 = 3.0 × 10⁵ m s⁻¹. (b) F = e(E − vB) = 1.60 × 10⁻¹⁹ × (1.5 × 10⁴ − 2.0 × 10⁵ × 0.050) = 8.00 × 10⁻¹⁶ N. (c) In the direction of the electric force, because the proton is slower than the selected speed. Mark scheme (5 marks). C1: selected speed. M1: F = e(E − vB). C1: value. B1: direction of electric force. A1: F = 8.0 × 10⁻¹⁶ N.', 5),
('a1c80bb3-a951-5258-a158-54d6fba07e11', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 46, 46, 'Electrons moving at 2.4 × 10⁷ m s⁻¹ pass between plates 5.0 cm long where E = 1.2 × 10⁴ V m⁻¹. (a) Calculate their deflection on leaving the plates with no magnetic field. (b) Calculate the magnetic flux density needed to cancel the deflection, in mT. (c) State the direction of this field relative to E and v. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '0.5 mT', 'mT', false, NULL, false, NULL, '(a) a = 1.60 × 10⁻¹⁹ × 1.2 × 10⁴ ÷ 9.11 × 10⁻³¹ = 2.11 × 10¹⁵ m s⁻²; t = 0.050 ÷ 2.4 × 10⁷ = 2.08 × 10⁻⁹ s; y = 0.5 × 2.108 × 10¹⁵ × (2.083 × 10⁻⁹)² = 0.00457 m. (b) B = E/v = 1.2 × 10⁴ ÷ 2.4 × 10⁷ = 5.0 × 10⁻⁴ T. In mT: 5.0 × 10⁻⁴ × 1000 = 0.50. (c) At right angles to both E and v. Mark scheme (6 marks). C1: acceleration. C1: deflection. M1: B = E/v. C1: conversion. B1: mutually perpendicular. A1: B = 0.50 mT.', 6),
('ae385b5f-5009-5b5a-864c-518e0131599e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 47, 47, 'Free electrons drift at 1.0 × 10⁻⁴ m s⁻¹ along a metal strip 1.0 cm wide, at right angles to a field of 0.50 T. They are pushed sideways until the electric field across the strip balances the magnetic force. (a) Calculate the electric field needed for balance. (b) Calculate the p.d. across the strip, in µV. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.5 uV', 'µV', false, NULL, false, NULL, '(a) eE = Bev, so E = vB = 1.0 × 10⁻⁴ × 0.50 = 5.0 × 10⁻⁵ V m⁻¹. (b) V = Ed = 5.0 × 10⁻⁵ × 0.010 = 5.0 × 10⁻⁷ V. In µV: 5.0 × 10⁻⁷ × 10⁶ = 0.50. Mark scheme (5 marks). M1: eE = Bev. C1: E = vB. C1: V = Ed. C1: conversion. A1: V = 0.50 µV.', 5),
('2c2c0c4d-95bf-59df-8a6b-c43d8f562ad3', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 48, 48, 'For a beam of fixed speed, the electric field needed to cancel the magnetic deflection is measured for several magnetic fields: B/mT = 0.50, 1.0, 1.5, 2.0 and E/10⁴ V m⁻¹ = 1.0, 2.0, 3.0, 4.0. The particles are electrons. (a) Explain why the graph of E against B is a straight line through the origin. (b) Calculate the speed of the electrons. (c) Calculate their kinetic energy, in eV. Give only the answer to (b). Take mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '2e7', 'm s⁻¹', false, NULL, false, NULL, '(a) E = vB with v constant. (b) v = gradient = 4.0 × 10⁴ ÷ 2.0 × 10⁻³ = 2.0 × 10⁷ m s⁻¹. (c) E_k = 0.5 × 9.11 × 10⁻³¹ × (2.0 × 10⁷)² ÷ 1.60 × 10⁻¹⁹ = 1140 eV. Mark scheme (6 marks). B1: E = vB. M1: gradient = v. C1: v. C1: ½mv². C1: in eV. A1: v = 2.0 × 10⁷ m s⁻¹.', 6),
('28b652fe-ba6f-58d4-99ee-c0d59c3705a4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 49, 49, 'A velocity selector is to select α-particles of kinetic energy 5.0 MeV (1 MeV = 1.6 × 10⁻¹³ J; mass 6.64 × 10⁻²⁷ kg) using B = 0.50 T. (a) Calculate their speed. (b) Calculate the electric field needed. (c) Comment on the p.d. needed across plates 1.0 cm apart. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '7.762e6', 'V m⁻¹', false, NULL, false, NULL, '(a) v = √(2E_k/m) = √(2 × 5.0 × 1.6 × 10⁻¹³ ÷ 6.64 × 10⁻²⁷) = 1.55 × 10⁷ m s⁻¹. (b) E = Bv = 0.50 × 1.552 × 10⁷ = 7.76 × 10⁶ V m⁻¹. (c) V = Ed ≈ 7.76 × 10⁴ V: very large, so sparking would be a problem. Mark scheme (5 marks). C1: speed. C1: E = Bv. C1: value. B1: impractically large p.d. A1: E = 7.76 × 10⁶ V m⁻¹.', 5),
('4f156a89-bdcc-5f97-8a23-ae68898be2d1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 50, 50, 'Deuterons (mass 3.34 × 10⁻²⁷ kg, charge e) are selected by crossed fields with E = 3.0 × 10⁴ V m⁻¹ and B = 0.10 T. They then move against an electric field until they stop. (a) Calculate their speed. (b) Calculate their kinetic energy. (c) Calculate the stopping p.d. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '939.4', 'V', false, NULL, false, NULL, '(a) v = 3.0 × 10⁴ ÷ 0.10 = 3.0 × 10⁵ m s⁻¹. (b) E_k = 0.5 × 3.34 × 10⁻²⁷ × (3.0 × 10⁵)² = 1.50 × 10⁻¹⁶ J. (c) eV = E_k, so V = 1.503 × 10⁻¹⁶ ÷ 1.60 × 10⁻¹⁹ = 939 V. Mark scheme (6 marks). C1: v = E/B. C1: ½mv². M1: eV = E_k. C1: value. B1: units consistent. A1: V = 939 V.', 6)
